INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('5-in-1-funpak-usa-europe', 'Game Gear', '5 in 1 Funpak (USA, Europe)', '1993', 'Compilation', 'Sega', '1', 'Various', 'Board and card game collection.', 'Win at Chess, Checkers, Backgammon, Reversi, and Yacht.', 'Five classic parlor games in one portable cartridge.', '5 in 1 Funpak is the perfect travel companion for Game Gear. Challenge the AI in five timeless board games, featuring clean 8-bit graphics and multiple difficulty levels for endless strategic fun on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aa-harimanada-japan', 'Game Gear', 'Aa Harimanada (Japan)', '1993', 'Sports', 'Sega', '2', 'Wrestling', 'One-on-one Sumo wrestling.', 'Push your opponent out of the ring to become Yokozuna.', 'A high-intensity Sumo simulation based on the anime.', 'Aa Harimanada brings the power of Sumo to your handheld. Master various grips, shoves, and throws to dominate the dohyo in this Japanese exclusive sports title known for its large, expressive character sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addams-family-the-usa-europe', 'Game Gear', 'Addams Family, The (USA, Europe)', '1993', 'Platform', 'Ocean Software', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue the Addams family members from the mansion.', 'A spooky and challenging platformer based on the hit film.', 'The Addams Family on Game Gear tasks Gomez with navigating a trap-filled estate. Explore the mansion’s secrets and defeat eerie foes to save your kin in this atmospheric and visually detailed 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-batman-&-robin-the-usa-europe', 'Game Gear', 'Adventures of Batman & Robin, The (USA, Europe)', '1994', 'Action', 'Clockwork Tortoise', '1', 'Superhero', 'Side-scrolling action shooter.', 'Stop the Joker and other villains from destroying Gotham.', 'Intense superhero action with high-quality 8-bit visuals.', 'The Adventures of Batman & Robin features gadget-based combat and smooth platforming. Use Batarangs and explosives to take down iconic bosses in this fast-paced handheld adaptation of the legendary animated series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerial-assault-japan-v11', 'Game Gear', 'Aerial Assault (Japan) (v1.1)', '1991', 'Shooter', 'Sanritsu Denki', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Destroy the enemy fleet and the ultimate superweapon.', 'A portable version of the technical Master System shmup.', 'Aerial Assault (v1.1) delivers high-flying aerial combat. Upgrade your jet with powerful weapons to navigate through intense enemy formations and massive bosses in this polished Japanese 8-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerial-assault-world', 'Game Gear', 'Aerial Assault (World)', '1991', 'Shooter', 'Sanritsu Denki', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Destroy the enemy fleet and the ultimate superweapon.', 'The international release of the high-speed aerial shooter.', 'Pilot your fighter jet through dangerous airspace in Aerial Assault. This worldwide version features tight controls and impressive sprite work, offering a pure arcade-style shooting experience for the Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-japan', 'Game Gear', 'Aladdin (Japan)', '1993', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Outrun the guards and defeat Jafar to win Jasmine.', 'A beautiful 8-bit adaptation of the Disney classic.', 'Aladdin (Japan) features fluid animation and vibrant colors that pop on the Game Gear screen. Navigate the streets of Agrabah and the Cave of Wonders in this charming and faithful handheld movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aladdin-usa-europe', 'Game Gear', 'Aladdin (USA, Europe)', '1993', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Outrun the guards and defeat Jafar to win Jasmine.', 'The international release of the iconic Disney platformer.', 'Experience the magic of Disney''s Aladdin on the go. Use apples and your agility to survive dangerous traps and enemies in this highly-regarded title, famous for its cinematic feel and excellent 8-bit soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-3-usa-europe', 'Game Gear', 'Alien 3 (USA, Europe)', '1992', 'Action', 'Probe Software', '1', 'Horror', 'Side-scrolling action shooter.', 'Rescue prisoners and reach the exit before time runs out.', 'A tense and atmospheric sci-fi survival shooter.', 'Alien 3 on Game Gear captures the dread of the film. Armed with pulse rifles and flamethrowers, navigate the Fiorina 161 colony to rescue trapped humans and eliminate the Xenomorph threat in this difficult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-syndrome-japan', 'Game Gear', 'Alien Syndrome (Japan)', '1991', 'Action', 'Sega', '2', 'Arcade', 'Top-down run and gun.', 'Rescue hostages and escape the infested space station.', 'A portable port of Sega’s iconic sci-fi horror arcade.', 'Alien Syndrome (Japan) features frantic 360-degree shooting action. Blast through grotesque alien lifeforms and find the exit before the station explodes in this high-tension, fast-paced 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-syndrome-usa-europe', 'Game Gear', 'Alien Syndrome (USA, Europe)', '1991', 'Action', 'Sega', '2', 'Arcade', 'Top-down run and gun.', 'Rescue hostages and escape the infested space station.', 'The Western release of the classic sci-fi shooter.', 'Fight for survival in Alien Syndrome. This Game Gear version offers challenging overhead combat and massive, screen-filling bosses, requiring quick reflexes and careful map navigation to save your comrades.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('andre-agassi-tennis-usa-europe', 'Game Gear', 'Andre Agassi Tennis (USA, Europe)', '1992', 'Sports', 'Sims', '2', 'Tennis', 'Sports simulation (Tennis).', 'Win the Grand Slam and reach the world #1 ranking.', 'Professional tennis endorsed by legend Andre Agassi.', 'Andre Agassi Tennis provides a deep and competitive sports experience. Choose your surface and master your serve and volley to climb the rankings in this polished handheld sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcade-classics-usa-europe', 'Game Gear', 'Arcade Classics (USA, Europe)', '1995', 'Compilation', 'Sega', '1', 'Arcade', 'Multi-game arcade collection.', 'Achieve high scores in Centipede, Missile Command, and Ultipede.', 'Three Atari arcade legends in one portable pack.', 'Arcade Classics brings timeless gameplay to the Game Gear. Experience pixel-perfect ports of Centipede and Missile Command, offering pure, addictive retro action that is perfect for short gaming bursts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arch-rivals-usa-europe', 'Game Gear', 'Arch Rivals (USA, Europe)', '1989', 'Sports', 'Midway', '2', 'Arcade', 'Sports simulation (Basketball).', 'Outscore the opponent in a 2v2 street ball match.', 'A punch-filled, "no-foul" arcade basketball port.', 'Arch Rivals is basketball with a twist: you can punch your way to the ball! Experience high-energy 2v2 action where the only thing that matters is the final score and the biggest hits on the court.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arena-usa-europe', 'Game Gear', 'Arena (USA, Europe)', '1995', 'Action', 'Sega', '1', 'Fantasy', 'Isometric action shooter.', 'Complete various combat missions to defeat the enemy.', 'A high-stakes tactical shooter with varied objectives.', 'Arena: Maze of Death tasks you with infiltrating enemy facilities. Use a variety of weapons and a mini-map to navigate complex, hazard-filled environments in this unique and challenging isometric 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ariel-the-little-mermaid-usa-europe', 'Game Gear', 'Ariel the Little Mermaid (USA, Europe)', '1993', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling action adventure.', 'Save the Seven Kingdoms from Ursula’s evil spell.', 'A colorful Disney adventure under the sea.', 'Ariel the Little Mermaid features unique swimming-based gameplay. Use your fish friends and magical powers to navigate coral reefs and defeat sea villains in this charming and visually vibrant handheld quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arliel---crystal-densetsu-japan', 'Game Gear', 'Arliel - Crystal Densetsu (Japan)', '1991', 'RPG', 'Sega', '1', 'Fantasy', 'Strategy RPG.', 'Lead your units to victory in tactical grid-based combat.', 'A Japanese exclusive fantasy strategy game.', 'Arliel - Crystal Densetsu is a deep tactical experience for Game Gear. Manage your party, utilize terrain advantages, and engage in turn-based battles to protect the crystals in this beautifully illustrated 8-bit RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-and-the-great-rescue-europe-enfrdeesit', 'Game Gear', 'Asterix and the Great Rescue (Europe) (En,Fr,De,Es,It)', '1993', 'Platform', 'Core Design', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Getafix and Dogmatix from the Romans.', 'A colorful European adventure starring the famous Gauls.', 'Asterix and the Great Rescue features both Asterix and Obelix with their unique abilities. Bash through Roman legions and solve environmental puzzles in this polished and challenging 8-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-and-the-great-rescue-usa', 'Game Gear', 'Asterix and the Great Rescue (USA)', '1993', 'Platform', 'Core Design', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Getafix and Dogmatix from the Romans.', 'North American release of the Gallic hero adventure.', 'Help Asterix and Obelix on their quest to save their village in this US version. This title is known for its high difficulty, detailed sprites, and creative use of the Game Gear’s color palette.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-and-the-secret-mission-europe-enfrde', 'Game Gear', 'Asterix and the Secret Mission (Europe) (En,Fr,De)', '1993', 'Platform', 'Core Design', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find the secret documents to stop the Roman invasion.', 'An expansive and beautiful 8-bit Asterix sequel.', 'Asterix and the Secret Mission offers smooth platforming and diverse levels. Switch between the fast Asterix and the powerful Obelix to navigate through forests and Roman camps in this refined handheld exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ax-battler---a-legend-of-golden-axe-usa-europe-v24', 'Game Gear', 'Ax Battler - A Legend of Golden Axe (USA, Europe) (v2.4)', '1991', 'Action', 'Sega', '1', 'Fantasy', 'Action adventure with RPG elements.', 'Defeat the forces of evil to recover the Golden Axe.', 'A Golden Axe spin-off starring the barbarian hero.', 'Ax Battler (USA/Europe) takes a different approach to the series, featuring a vast overworld and random encounters. Explore the land of Firewood and master sword techniques in this unique handheld hybrid of action and RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ax-battler---golden-axe-densetsu-japan-v15', 'Game Gear', 'Ax Battler - Golden Axe Densetsu (Japan) (v1.5)', '1991', 'Action', 'Sega', '1', 'Fantasy', 'Action adventure with RPG elements.', 'Defeat the forces of evil to recover the Golden Axe.', 'The original Japanese version of the Ax Battler quest.', 'Ax Battler - Golden Axe Densetsu (v1.5) provides a deep fantasy adventure. Navigate through treacherous dungeons and engage in 1v1 combat to prove your worth as a legendary warrior in this polished 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ayrton-sennas-super-monaco-gp-ii-japan', 'Game Gear', 'Ayrton Senna''s Super Monaco GP II (Japan)', '1992', 'Racing', 'Sega', '1', 'Simulation', 'Behind-the-back racing.', 'Win the F1 World Championship with Senna’s guidance.', 'The Japanese edition of the legendary F1 sequel.', 'Ayrton Senna''s Super Monaco GP II is a technical masterpiece for Game Gear. Experience the speed of Formula One with advice from the legend himself, featuring smooth scaling and a deep career mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ayrton-sennas-super-monaco-gp-ii-usa-europe', 'Game Gear', 'Ayrton Senna''s Super Monaco GP II (USA, Europe)', '1992', 'Racing', 'Sega', '1', 'Simulation', 'Behind-the-back racing.', 'Win the F1 World Championship with Senna’s guidance.', 'The international release of the premier F1 sim.', 'Take to the track in the Western version of Super Monaco GP II. Featuring authentic circuits and high-speed racing, this title pushed the Game Gear hardware to its limits to deliver a true professional racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baku-baku-animal-japan', 'Game Gear', 'Baku Baku Animal (Japan)', '1994', 'Puzzle', 'Sega', '2', 'Cute', 'Falling block puzzle.', 'Match animal blocks with their favorite foods to clear them.', 'A frantic and adorable Japanese puzzle game.', 'Baku Baku Animal is a cult classic that rewards fast thinking. Chain together massive combos by feeding your animals in this high-energy, colorful competitive puzzle game from Sega.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baku-baku-animal-usa', 'Game Gear', 'Baku Baku Animal (USA)', '1994', 'Puzzle', 'Sega', '2', 'Cute', 'Falling block puzzle.', 'Match animal blocks with their favorite foods to clear them.', 'The Western release of the high-speed puzzle hit.', 'Experience the addictive "Food-Chain" puzzle mechanics of Baku Baku. Master the timing and placement of your blocks to outscore the AI or a friend in this vibrant and charming 8-bit handheld gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-super-model-proto', 'Game Gear', 'Barbie Super Model (Proto)', '1993', 'Platform', 'Hi Tech Expressions', '1', 'Fashion', 'Lifestyle simulation / Mini-games.', 'Complete fashion and photography challenges.', 'An unreleased prototype featuring the fashion icon.', 'Barbie Super Model (Proto) offers a rare look at the unreleased Game Gear title. Navigate fashion runways and practice your poses in this collection of mini-games designed for the younger audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bartman-meets-radioactive-man-usa-europe', 'Game Gear', 'Bartman Meets Radioactive Man (USA, Europe)', '1991', 'Action', 'Imagineering', '1', 'Superhero', 'Side-scrolling action platformer.', 'Stop the Space Mutants and the evil Radioactive Man.', 'A superhero parody adventure starring Bart Simpson.', 'Bartman Meets Radioactive Man features Bart using his cape and gadgets to fight crime. Navigate through comic-book inspired levels and defeat wacky bosses in this colorful and humorous 8-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-forever-usa-europe', 'Game Gear', 'Batman Forever (USA, Europe)', '1995', 'Action', 'Probe Software', '1', 'Superhero', 'One-on-one fighting game.', 'Defeat all rivals to reach the Riddler and Two-Face.', 'A dark and gritty 1v1 fighter based on the movie.', 'Batman Forever brings the theatrical experience to the Game Gear. Master a variety of martial arts moves and gadgets to take down Gotham’s most dangerous criminals in this visually moody fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-returns-world', 'Game Gear', 'Batman Returns (World)', '1992', 'Action', 'Arc Developments', '1', 'Movie', 'Side-scrolling action platformer.', 'Stop the Penguin and Catwoman from taking over Gotham.', 'A cinematic action game based on the Tim Burton film.', 'Batman Returns features branching paths and high-speed grappling hook mechanics. Battle through a snowy Gotham City to dismantle the Red Triangle Circus Gang in this polished and atmospheric 8-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batter-up-usa-europe', 'Game Gear', 'Batter Up (USA, Europe)', '1992', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Win the game by outscoring the opponent.', 'A vibrant and accessible 8-bit baseball sim.', 'Batter Up delivers fast-paced baseball action on the go. Featuring intuitive batting and pitching mechanics, this title offers a full league experience with colorful sprites that shine on the Game Gear’s screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battleship-usa-europe', 'Game Gear', 'Battleship (USA, Europe)', '1993', 'Strategy', 'Mindscape', '2', 'Board', 'Strategy board game.', 'Sink the entire enemy fleet before yours is destroyed.', 'A high-stakes digital version of the classic naval game.', 'Battleship for Game Gear adds cinematic flair to the tabletop classic. Use radar and strategic positioning to hunt down enemy vessels in this tense battle of wits and luck.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battletoads-europe', 'Game Gear', 'Battletoads (Europe)', '1992', 'Action', 'Rare', '1', 'Arcade', 'Side-scrolling beat ''em up.', 'Rescue your partners and defeat the Dark Queen.', 'A notoriously difficult and high-energy brawler.', 'Battletoads (Europe) brings the intense action of the ''Toads to the handheld. Master the "Smash Hit" attacks and survive the infamous vehicle levels in this technically impressive and punishingly fun 8-bit port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battletoads-usa', 'Game Gear', 'Battletoads (USA)', '1992', 'Action', 'Rare', '1', 'Arcade', 'Side-scrolling beat ''em up.', 'Rescue your partners and defeat the Dark Queen.', 'The North American release of the extreme brawler.', 'Battletoads on Game Gear features large sprites and fluid animation. Experience the extreme combat and varied gameplay styles that made this series a legend in the action genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beavis-and-butt-head-usa-europe', 'Game Gear', 'Beavis and Butt-head (USA, Europe)', '1994', 'Platform', 'Viacom New Media', '1', 'Comedy', 'Adventure / Mini-games.', 'Find the pieces of the GWAR concert tickets.', 'A crude and hilarious adventure starring the MTV duo.', 'Beavis and Butt-head tasks you with navigating Highland to find ripped ticket pieces. Complete bizarre tasks and avoid trouble in this faithful 8-bit recreation of the show''s signature humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beavis-and-butt-head-usa-europe-option-menu-different', 'Game Gear', 'Beavis and Butt-head (USA, Europe) (Option-Menu different)', '1994', 'Platform', 'Viacom New Media', '1', 'Comedy', 'Adventure / Mini-games.', 'Find the pieces of the GWAR concert tickets.', 'Variant version with a different options menu.', 'This specific version of Beavis and Butt-head features menu tweaks but retains the same couch-potato chaos. Explore various locations and solve puzzles to make it to the concert of the century.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('berenstain-bears-camping-adventure-the-usa', 'Game Gear', 'Berenstain Bears'' Camping Adventure, The (USA)', '1994', 'Platform', 'Spidersoft', '1', 'Cartoon', 'Side-scrolling platformer.', 'Complete the camping trip and find the lost cubs.', 'A charming and family-friendly forest adventure.', 'The Berenstain Bears'' Camping Adventure features Brother and Sister Bear in a colorful outdoor quest. Navigate through caves and forests while collecting items in this gentle and visually pleasing handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('berlin-no-kabe-japan', 'Game Gear', 'Berlin no Kabe (Japan)', '1991', 'Puzzle', 'Sega', '1', 'Abstract', 'Action puzzle game.', 'Break blocks to defeat enemies and clear the wall.', 'A unique Japanese "break-out" style action game.', 'Berlin no Kabe (The Berlin Wall) tasks you with breaking blocks to trap enemies and fall through layers of the wall. It’s a fast-paced, strategic arcade game with a quirky premise and addictive loop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailor-moon-s-english', 'Game Gear', 'Bishoujo Senshi Sailor Moon S (English)', '1995', 'Action', 'Banpresto', '1', 'Anime', 'One-on-one fighting game.', 'Win the tournament and protect the world.', 'English fan-translated version of the Sailor Moon fighter.', 'Bishoujo Senshi Sailor Moon S allows Western fans to enjoy the Japanese fighter. Control your favorite Sailor Guardian and master their special moves in this vibrant and competitive 8-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bishoujo-senshi-sailor-moon-s-japan', 'Game Gear', 'Bishoujo Senshi Sailor Moon S (Japan)', '1995', 'Action', 'Banpresto', '1', 'Anime', 'One-on-one fighting game.', 'Win the tournament and protect the world.', 'The original Japanese Sailor Moon fighting game.', 'Sailor Moon S on Game Gear features impressive character portraits and smooth combat. Experience the magical girl action in this handheld exclusive that captures the spirit of the iconic anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bonkers-wax-up!-usa-europe', 'Game Gear', 'Bonkers Wax Up! (USA, Europe)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Capture the toon criminals across Hollywood.', 'A frantic and colorful platformer starring Bonkers D. Bobcat.', 'Bonkers Wax Up! features diverse levels based on the Disney cartoon. Use Bonkers'' speed and agility to navigate studio sets and trap villains in this visually bright and energetic handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bram-stokers-dracula-usa-europe', 'Game Gear', 'Bram Stoker''s Dracula (USA, Europe)', '1993', 'Action', 'Psygnosis', '1', 'Horror', 'Side-scrolling action platformer.', 'Navigate the night and defeat the King of Vampires.', 'A dark and atmospheric movie-based action game.', 'Bram Stoker''s Dracula features gothic visuals and challenging combat. Fight through the Transylvanian countryside as Jonathan Harker in a race to destroy the legendary Count Dracula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble-prototype', 'Game Gear', 'Bubble Bobble (Prototype)', '1993', 'Platform', 'Taito', '2', 'Cute', 'Fixed-screen platformer.', 'Trap all enemies in bubbles and pop them.', 'Rare prototype of the legendary arcade puzzle-actioner.', 'This Bubble Bobble prototype offers a look at the development of the 8-bit handheld port. Test the bubble-popping mechanics in this early build of one of gaming''s most addictive titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bubble-bobble-usa-europe', 'Game Gear', 'Bubble Bobble (USA, Europe)', '1993', 'Platform', 'Taito', '2', 'Cute', 'Fixed-screen platformer.', 'Trap all enemies in bubbles and pop them.', 'The final handheld version of the arcade classic.', 'Bubble Bobble for Game Gear is a perfect portable conversion. Navigate 100 levels of bubble-bursting fun, either solo or with a friend, to rescue your girlfriends from the Cave of Monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-bunny-in-double-trouble-usa-europe', 'Game Gear', 'Bugs Bunny in Double Trouble (USA, Europe)', '1993', 'Platform', 'Atod', '1', 'Cartoon', 'Side-scrolling platformer.', 'Escape from the dream world and find your way back home.', 'A wacky Looney Tunes adventure starring Bugs Bunny.', 'Bugs Bunny in Double Trouble features vibrant graphics and classic cartoon humor. Use a variety of gadgets to outsmart Yosemite Sam and Marvin the Martian in this fast-paced handheld platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bust-a-move-usa-europe', 'Game Gear', 'Bust-A-Move (USA, Europe)', '1994', 'Puzzle', 'Taito', '2', 'Cute', 'Bubble-matching puzzle.', 'Clear the screen by matching three or more bubbles.', 'The portable version of the addictive puzzle hit.', 'Bust-A-Move (Puzzle Bobble) brings the color-matching sensation to your pocket. Aim your launcher and clear the board in this high-pressure, endlessly replayable 8-bit puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buster-ball-japan', 'Game Gear', 'Buster Ball (Japan)', '1994', 'Sports', 'Sega', '2', 'Arcade', 'Top-down futuristic sports.', 'Score goals by knocking the ball into the net.', 'A fast-paced, sci-fi take on soccer/hockey.', 'Buster Ball (known as Heavyweight Hockey elsewhere) features armored athletes in a brutal arena. Use power shots and physical force to dominate the competition in this high-energy futuristic sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buster-fight-japan', 'Game Gear', 'Buster Fight (Japan)', '1994', 'Fighting', 'Sega', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat all challengers to become the champion.', 'A Japanese exclusive fighter with large character sprites.', 'Buster Fight delivers impressive 1v1 combat for the Game Gear. Featuring a diverse roster of fighters and fluid special moves, it stands as one of the most competent traditional fighters on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('caesars-palace-usa-europe', 'Game Gear', 'Caesars Palace (USA, Europe)', '1992', 'Board', 'Sega', '2', 'Casino', 'Casino simulation.', 'Win big in Blackjack, Roulette, and Slots.', 'A comprehensive gambling simulation.', 'Caesars Palace brings the thrill of the Las Vegas strip to your handheld. Manage your bankroll and test your luck across multiple casino classics in this detailed 8-bit simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('captain-america-and-the-avengers-usa-europe', 'Game Gear', 'Captain America and the Avengers (USA, Europe)', '1992', 'Action', 'Data East', '2', 'Superhero', 'Side-scrolling beat ''em up.', 'Defeat the Mandarin and his army to save the world.', 'A superhero brawler featuring Earth''s Mightiest Heroes.', 'Captain America and the Avengers allows you to control Cap and Hawkeye. Use your shield and arrows to fight through waves of enemies in this action-packed 8-bit arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('car-licence-japan', 'Game Gear', 'Car Licence (Japan)', '1991', 'Racing', 'Sega', '1', 'Simulation', 'Driving simulation / Quiz.', 'Pass the driving test to earn your license.', 'A quirky Japanese educational driving game.', 'Car Licence tasks you with navigating city streets and following traffic laws. It’s a unique mix of driving simulation and logic puzzles exclusive to the Japanese Game Gear market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('casino-funpak-usa', 'Game Gear', 'Casino Funpak (USA)', '1993', 'Compilation', 'Sega', '1', 'Casino', 'Casino simulation.', 'Win the jackpot in various gambling games.', 'A portable collection of casino favorites.', 'Casino Funpak offers quick partidas of Poker, Solitaire, and Slots. It’s the perfect "pick-up-and-play" title for those looking to test their luck without losing real money.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castle-of-illusion-starring-mickey-mouse-usa-europe', 'Game Gear', 'Castle of Illusion Starring Mickey Mouse (USA, Europe)', '1990', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Minnie Mouse from the witch Mizrabel.', 'A masterpiece of 8-bit platforming.', 'Castle of Illusion is a crown jewel of the Game Gear library. Navigate through magical worlds with stunning graphics and a charming soundtrack in this definitive Mickey Mouse adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chakan-usa-europe', 'Game Gear', 'Chakan (USA, Europe)', '1992', 'Action', 'Extended Play Productions', '1', 'Fantasy', 'Side-scrolling action platformer.', 'Hunt the dark forces through the ages to win eternal rest.', 'A dark, atmospheric, and difficult action epic.', 'Chakan: The Forever Man features gothic art and complex combat. Use alchemy and diverse weapons to defeat the masters of the underworld in this challenging and visually unique title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chessmaster-the-usa-europe', 'Game Gear', 'Chessmaster, The (USA, Europe)', '1991', 'Board', 'Software Toolworks', '2', 'Chess', 'Board game simulation.', 'Defeat the computer in a match of high-level chess.', 'A sophisticated portable chess engine.', 'The Chessmaster provides a deep challenge for beginners and grandmasters alike. Featuring multiple difficulty levels and a clean interface, it’s the ultimate way to play chess on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chicago-syndicate-usa-europe', 'Game Gear', 'Chicago Syndicate (USA, Europe)', '1995', 'Action', 'Konami', '1', 'Arcade', 'Side-scrolling action adventure.', 'Dismantle the criminal syndicate and take over the city.', 'A gritty crime-themed brawler with RPG elements.', 'Chicago Syndicate is a spin-off of the Eternal Champions series. Navigate the city, upgrade your fighter, and take down rival gang leaders in this deep and atmospheric 8-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('choplifter-iii-usa-europe', 'Game Gear', 'Choplifter III (USA, Europe)', '1993', 'Shooter', 'Beam Software', '1', 'Arcade', 'Side-scrolling helicopter shooter.', 'Rescue hostages and bring them to the base safely.', 'High-tension aerial rescue action.', 'Choplifter III tasks you with piloting a combat chopper into enemy territory. Balance combat and rescue missions across multiple war zones in this polished and difficult 8-bit sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock-world', 'Game Gear', 'Chuck Rock (World)', '1991', 'Platform', 'Core Design', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Ophelia from the Gary Gritter.', 'A prehistoric comedy adventure.', 'Chuck Rock features the belly-bumping caveman in a vibrant 8-bit world. Throw rocks and use your strength to navigate through dinosaur-filled levels in this charming and humorous platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock-ii---son-of-chuck-europe', 'Game Gear', 'Chuck Rock II - Son of Chuck (Europe)', '1993', 'Platform', 'Core Design', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue your father from the evil kidnappers.', 'A polished sequel starring Chuck Rock’s son.', 'Chuck Rock II: Son of Chuck improves on the original with better graphics and smoother gameplay. Control Junior and use his rattle to bash enemies in this creative European-exclusive platforming hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chuck-rock-ii---son-of-chuck-usa', 'Game Gear', 'Chuck Rock II - Son of Chuck (USA)', '1993', 'Platform', 'Core Design', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue your father from the evil kidnappers.', 'The North American release of the prehistoric sequel.', 'Junior takes center stage in Son of Chuck. Explore colorful prehistoric environments and face massive bosses in this high-quality 8-bit platformer that pushes the Game Gear''s color capabilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cliffhanger-usa-europe', 'Game Gear', 'Cliffhanger (USA, Europe)', '1993', 'Action', 'Sony Imagesoft', '1', 'Movie-based', 'Side-scrolling beat ''em up.', 'Survive the mountain peaks and recover the stolen money.', 'A rugged mountain brawler based on the Stallone film.', 'Cliffhanger brings the high-altitude action to your handheld. Scale snowy cliffs and fight through waves of mercenaries using hand-to-hand combat and weapons in this intense 8-bit survival adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('clutch-hitter-usa-europe', 'Game Gear', 'Clutch Hitter (USA, Europe)', '1993', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Lead your team to victory in a full baseball season.', 'A portable version of Sega''s arcade baseball hit.', 'Clutch Hitter offers a realistic baseball experience on the Game Gear. With smooth pitching and batting mechanics, it provides a solid sports challenge that captures the excitement of the big leagues.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('coca-cola-kid-japan', 'Game Gear', 'Coca Cola Kid (Japan)', '1994', 'Action', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Navigate the city to save your teacher and friends.', 'A Japan-exclusive platformer with a famous brand.', 'Coca-Cola Kid is a hidden gem known for its fluid movement and vibrant color palette. Use your skateboard and kicks to clear urban levels in this highly polished and energetic handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('coca-cola-kid-japan-en-by-filler-v10', 'Game Gear', 'Coca Cola Kid (Japan) [En by Filler v1.0]', '1994', 'Action', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Navigate the city to save your teacher and friends.', 'English fan-translated version of the Coca-Cola hit.', 'This English localized version allows Western players to fully enjoy Coca-Cola Kid. Experience the fast-paced action and unique brand-integrated power-ups of this Japanese classic with translated text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('columns-japan', 'Game Gear', 'Columns (Japan)', '1990', 'Puzzle', 'Sega', '2', 'Abstract', 'Falling block puzzle.', 'Align three jewels of the same color to clear them.', 'The original Japanese version of the puzzle legend.', 'Columns (Japan) is a relaxing yet challenging test of logic. Strategize your jewel placements to create chains and high scores in this portable conversion of Sega''s quintessential arcade puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('columns-usa-europe', 'Game Gear', 'Columns (USA, Europe)', '1990', 'Puzzle', 'Sega', '2', 'Abstract', 'Falling block puzzle.', 'Align three jewels of the same color to clear them.', 'The definitive international version of the puzzle hit.', 'Columns on Game Gear is a perfect travel companion. Match gems vertically, horizontally, or diagonally in this endlessly addictive puzzle game that shines on the handheld’s color screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cool-spot-usa-europe', 'Game Gear', 'Cool Spot (USA, Europe)', '1993', 'Platform', 'Virgin Interactive', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue the other "Spots" and reach the end of the level.', 'A visually stunning adventure starring the 7-Up mascot.', 'Cool Spot features incredibly smooth animation and catchy music. Help the red dot jump and shoot soda bubbles across beach and toy-themed levels in this high-quality 8-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cosmic-spacehead-europe', 'Game Gear', 'Cosmic Spacehead (Europe)', '1993', 'Adventure', 'Codemasters', '1', 'Comedy', 'Multi-genre adventure.', 'Find a way home by interacting with aliens and solving puzzles.', 'A quirky blend of point-and-click and platforming.', 'Cosmic Spacehead takes you on a surreal journey. Explore alien worlds, collect inventory items, and survive platforming segments in this colorful and humorous intergalactic quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crayon-shin-chan---taiketsu!-kantam-panic!!-japan', 'Game Gear', 'Crayon Shin-chan - Taiketsu! Kantam Panic!! (Japan)', '1995', 'Action', 'Banpresto', '1', 'Anime', 'Mini-game collection.', 'Win various school-themed games as Shin-chan.', 'A quirky Japanese exclusive based on the popular anime.', 'Crayon Shin-chan: Taiketsu! Kantam Panic!! features the mischievous preschooler in a series of wacky challenges. It’s a vibrant and funny collection of mini-games that perfectly capture the show''s humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crazy-faces-prototype', 'Game Gear', 'Crazy Faces (Prototype)', '1994', 'Puzzle', 'Sega', '1', 'Casual', 'Sliding tile puzzle.', 'Arrange the pieces to reveal crazy faces.', 'An unreleased prototype of a logic puzzle game.', 'Crazy Faces (Proto) offers a look at a "lost" Game Gear title. Slide tiles to complete comical portraits in this simple yet challenging puzzle game designed for quick handheld sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('crystal-warriors-usa-europe', 'Game Gear', 'Crystal Warriors (USA, Europe)', '1991', 'Strategy', 'Sega', '2', 'Fantasy', 'Tactical strategy RPG.', 'Command your units and capture the enemy capital.', 'A deep and colorful fantasy strategy masterpiece.', 'Crystal Warriors is a standout RPG on the system. Use an elemental rock-paper-scissors combat system to command mages and warriors in strategic turn-based battles to save the kingdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cutthroat-island-usa-europe', 'Game Gear', 'Cutthroat Island (USA, Europe)', '1995', 'Action', 'Ocean Software', '1', 'Movie-based', 'Side-scrolling action.', 'Find the treasure of Cutthroat Island before your rivals.', 'A pirate-themed brawler based on the Hollywood movie.', 'Cutthroat Island features intense swordplay and platforming. Navigate through jungles and pirate ships as Morgan or William in a race to find the legendary hidden gold.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('daffy-duck-in-hollywood-europe-enfrdeesit', 'Game Gear', 'Daffy Duck in Hollywood (Europe) (En,Fr,De,Es,It)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find the golden movie awards and stop the villains.', 'A high-energy cartoon adventure starring Daffy Duck.', 'Daffy Duck in Hollywood features diverse levels and wacky gadgets. Use your bubble-firing gun to defeat enemies and reclaim movie history in this visually impressive European exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('deep-duck-trouble-starring-donald-duck-usa-europe', 'Game Gear', 'Deep Duck Trouble Starring Donald Duck (USA, Europe)', '1993', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Solve the mystery of the cursed valley and find the treasure.', 'A stunning adventure starring Donald Duck.', 'Deep Duck Trouble features incredible 8-bit graphics and creative mechanics. Help Donald navigate through jungles and ice caves in this spiritual successor to the Lucky Dime Caper.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('defenders-of-oasis-usa-europe', 'Game Gear', 'Defenders of Oasis (USA, Europe)', '1992', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based RPG.', 'Assemble a team of heroes to defeat the dark wizard.', 'An epic and visually beautiful Arabian-themed RPG.', 'Defenders of Oasis is one of the Game Gear''s finest RPGs. Featuring an engaging story and high-quality battle sprites, explore the desert and ancient ruins to restore peace to the kingdom of Shahrzad.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-speedtrap-europe-enfrdeesit', 'Game Gear', 'Desert Speedtrap (Europe) (En,Fr,De,Es,It)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Outrun Wile E. Coyote and reach the goal.', 'A fast-paced Looney Tunes chase game.', 'Desert Speedtrap features the Road Runner in a race against time. Use your speed and agility to dodge traps and outsmart the coyote in this vibrant and difficult European platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-speedtrap-usa', 'Game Gear', 'Desert Speedtrap (USA)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Outrun Wile E. Coyote and reach the goal.', 'The North American version of the Road Runner adventure.', 'Race through the desert in the US version of Desert Speedtrap. This title is a test of reflexes, requiring quick jumps and bird seed collection to maintain your speed and survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('desert-strike---return-to-the-gulf-usa-europe', 'Game Gear', 'Desert Strike - Return to the Gulf (USA, Europe)', '1992', 'Strategy', 'Electronic Arts', '1', 'Modern Military', 'Isometric vehicular shooter.', 'Complete rescue and destruction missions with a helicopter.', 'A technical port of the classic military action game.', 'Desert Strike brings the 16-bit hit to the Game Gear. Pilot an Apache chopper through the desert, managing fuel and ammo while rescuing POWs and destroying enemy installations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('devilish-europe', 'Game Gear', 'Devilish (Europe)', '1992', 'Puzzle', 'Genki', '1', 'Abstract', 'Vertical scrolling pinball-action.', 'Reach the top of the tower by hitting enemies and bosses.', 'A unique hybrid of pinball and action-adventure.', 'Devilish (Europe) is an innovative title where you control a paddle to launch a ball-like warrior. Scale levels and defeat demonic bosses in this creative twist on the breakout genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('devilish-japan', 'Game Gear', 'Devilish (Japan)', '1992', 'Puzzle', 'Genki', '1', 'Abstract', 'Vertical scrolling pinball-action.', 'Reach the top of the tower by hitting enemies and bosses.', 'The original Japanese version of the pinball-actioner.', 'Devilish: Monster Prince features atmospheric music and challenging vertical levels. Use your paddle to guide your projectile through a dark fantasy world in this fast-paced handheld exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('devilish-usa', 'Game Gear', 'Devilish (USA)', '1992', 'Puzzle', 'Genki', '1', 'Abstract', 'Vertical scrolling pinball-action.', 'Reach the top of the tower by hitting enemies and bosses.', 'North American release of the gothic pinball game.', 'Experience the unique "Action-Paddle" gameplay of Devilish in the US. With varied stages and screen-filling bosses, it’s a refreshing departure from standard pinball simulations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donald-duck-no-4-tsu-no-hihou-japan', 'Game Gear', 'Donald Duck no 4-Tsu no Hihou (Japan)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Travel the world to find four legendary treasures.', 'The Japanese version of Deep Duck Trouble.', 'Donald Duck no 4-Tsu no Hihou showcases the Game Gear’s color depth. Guide Donald through beautifully drawn environments in his quest to find ancient artifacts for Uncle Scrooge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donald-duck-no-lucky-dime-japan', 'Game Gear', 'Donald Duck no Lucky Dime (Japan)', '1991', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Donald''s nephews and find Scrooge''s lucky dime.', 'The Japanese version of The Lucky Dime Caper.', 'Donald Duck no Lucky Dime is a charming and polished platformer. Choose your route through global locations and use Donald’s hammer to clear the way in this classic Sega title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('donald-no-magical-world-japan-enja', 'Game Gear', 'Donald no Magical World (Japan) (En,Ja)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Solve the mystery of the magical world to save your friends.', 'The Japanese version of the Mickey/Donald crossover.', 'Donald no Magical World (known as World of Illusion elsewhere) features beautiful graphics and cooperative-style gameplay elements. Experience the magic of Disney on the small screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('doraemon---waku-waku-pocket-paradise-japan', 'Game Gear', 'Doraemon - Waku Waku Pocket Paradise (Japan)', '1996', 'Adventure', 'Sega', '1', 'Anime', 'Board game / Mini-games.', 'Compete with Doraemon and friends in various games.', 'A Japanese exclusive featuring the famous robotic cat.', 'Doraemon: Waku Waku Pocket Paradise is a charming collection of mini-games and board game segments. It captures the heart of the anime with colorful sprites and accessible gameplay for all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-usa-europe', 'Game Gear', 'Double Dragon (USA, Europe)', '1992', 'Beat ''em up', 'Technos Japan', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Defeat the Black Warriors and rescue Marian.', 'A handheld port of the definitive arcade brawler.', 'Double Dragon on Game Gear features the iconic Lee brothers in portable form. Punch, kick, and use weapons to clear the streets in this classic 8-bit conversion of the arcade legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('double-dragon-usa-europe-beta', 'Game Gear', 'Double Dragon (USA, Europe) (Beta)', '1992', 'Beat ''em up', 'Technos Japan', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Defeat the Black Warriors and rescue Marian.', 'Beta version of the portable Lee brothers brawler.', 'This Double Dragon Beta offers a glimpse into the handheld development of the series. Experience the core combat and level layouts in this early 8-bit build.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dr-robotniks-mean-bean-machine-usa-europe', 'Game Gear', 'Dr. Robotnik''s Mean Bean Machine (USA, Europe)', '1993', 'Puzzle', 'Sega', '2', 'Cute', 'Falling block puzzle.', 'Match colored beans to clear them and defeat Robotnik.', 'The Sonic-themed Western version of Puyo Puyo.', 'Dr. Robotnik''s Mean Bean Machine is a high-speed, addictive puzzle game. Chain together combos to send "garbage" beans to your opponent in this colorful and competitive handheld hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon---the-bruce-lee-story-europe', 'Game Gear', 'Dragon - The Bruce Lee Story (Europe)', '1993', 'Action', 'Virgin Interactive', '1', 'Movie-based', 'One-on-one fighting game.', 'Win every fight to fulfill your destiny as a master.', 'European release of the martial arts movie game.', 'Dragon: The Bruce Lee Story features the life and battles of the legend. Use Bruce''s speed and unique fighting style to defeat rivals in this visually impressive 8-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon---the-bruce-lee-story-usa', 'Game Gear', 'Dragon - The Bruce Lee Story (USA)', '1993', 'Action', 'Virgin Interactive', '1', 'Movie-based', 'One-on-one fighting game.', 'Win every fight to fulfill your destiny as a master.', 'North American version of the Bruce Lee fighter.', 'Master the art of Jeet Kune Do in this US version. Battle through key moments from the film in a series of challenging 1v1 encounters that push the Game Gear''s combat mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-crystal---tsurani-no-meikyuu-japan', 'Game Gear', 'Dragon Crystal - Tsurani no Meikyuu (Japan)', '1990', 'Action', 'Sega', '1', 'Roguelike', 'Turn-based Roguelike.', 'Navigate the 30-floor dungeon and find the exit.', 'The original Japanese version of the cult classic crawler.', 'Dragon Crystal (Japan) is a pioneering "mystery dungeon" game for handhelds. Every time you enter, the layout changes, offering a fresh challenge as you collect armor and hatch eggs to survive the labyrinth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-crystal-usa-europe', 'Game Gear', 'Dragon Crystal (USA, Europe)', '1990', 'Action', 'Sega', '1', 'Roguelike', 'Turn-based Roguelike.', 'Navigate the 30-floor dungeon and find the exit.', 'A deep and addictive portable dungeon crawler.', 'Dragon Crystal brings Roguelike depth to the Game Gear. Battle through 30 randomly generated levels, managing your food supply and equipment in this atmospheric and highly replayable 8-bit RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dropzone-usa', 'Game Gear', 'Dropzone (USA)', '1987', 'Shooter', 'Archer Maclean', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Protect the scientists and defeat the alien invaders.', 'A fast-paced arcade shooter for the portable era.', 'Dropzone delivers intense Defender-style action on the go. Maneuver your jetpack-clad hero through waves of enemies with lightning-fast scrolling and explosive 8-bit effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dunk-kids-japan', 'Game Gear', 'Dunk Kids (Japan)', '1991', 'Sports', 'Sega', '2', 'Basketball', 'Sports simulation (Basketball).', 'Win the 3v3 streetball match to become the champion.', 'A Japanese exclusive street basketball sim.', 'Dunk Kids features vibrant anime-style graphics and high-energy 3v3 action. Master dunks and blocks in this fast-paced sports title that captures the urban spirit of street ball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-headdy-earlier-game-gear-prototype', 'Game Gear', 'Dynamite Headdy (Earlier Game Gear Prototype)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Use your detachable head to defeat the Dark Demon.', 'An early prototype of the cult-classic platformer.', 'This Dynamite Headdy Prototype offers a fascinating look at the development of Treasure’s masterpiece. Experience the unique head-swapping mechanics in an early, unfinished state.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-headdy-japan', 'Game Gear', 'Dynamite Headdy (Japan)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Use your detachable head to defeat the Dark Demon.', 'The original Japanese version of the surreal platformer.', 'Dynamite Headdy (Japan) is a visual tour de force on the Game Gear. Use 17 different heads with unique powers to navigate a theatrical stage world in this creative and technically impressive 8-bit hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamite-headdy-usa-europe', 'Game Gear', 'Dynamite Headdy (USA, Europe)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Use your detachable head to defeat the Dark Demon.', 'The international release of the high-energy platformer.', 'Experience the chaotic brilliance of Dynamite Headdy. Featuring massive bosses and inventive level design, this version brings the "puppet-show" action to your handheld with stunning color and speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-usa-europe', 'Game Gear', 'Earthworm Jim (USA, Europe)', '1994', 'Platform', 'Shiny Entertainment', '1', 'Cartoon', 'Side-scrolling action platformer.', 'Rescue Princess What''s-Her-Name and defeat Psy-Crow.', 'A wacky and beautifully animated 8-bit conversion.', 'Earthworm Jim on Game Gear captures the surreal humor of the original. Use your head as a whip and blast through gross-out levels in this technically ambitious and funny portable adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco-ii---the-tides-of-time-usa-europe', 'Game Gear', 'Ecco II - The Tides of Time (USA, Europe)', '1994', 'Action', 'Sega', '1', 'Adventure', 'Action adventure (Ocean).', 'Save the future of the ocean from the Vortex queen.', 'A cinematic and visually stunning aquatic sequel.', 'Ecco II: The Tides of Time features incredible 8-bit parallax scrolling. Swim through time and space, utilizing new transformations to solve environmental puzzles in this atmospheric masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco-the-dolphin-japan', 'Game Gear', 'Ecco the Dolphin (Japan)', '1992', 'Action', 'Sega', '1', 'Adventure', 'Action adventure (Ocean).', 'Rescue your pod and stop the alien invasion.', 'The Japanese version of the iconic dolphin adventure.', 'Ecco the Dolphin (Japan) brings the beautiful, haunting atmosphere of the sea to the Game Gear. Solve puzzles and navigate dangerous depths in this high-quality portable conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco-the-dolphin-usa', 'Game Gear', 'Ecco the Dolphin (USA)', '1992', 'Action', 'Sega', '1', 'Adventure', 'Action adventure (Ocean).', 'Rescue your pod and stop the alien invasion.', 'The North American release of the aquatic classic.', 'Dive into a massive 8-bit ocean in the US version of Ecco the Dolphin. Master the sonar and leaping mechanics to uncover an intergalactic mystery in this challenging and artistic handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecco-the-dolphin-ii-japan', 'Game Gear', 'Ecco the Dolphin II (Japan)', '1994', 'Action', 'Sega', '1', 'Adventure', 'Action adventure (Ocean).', 'Save the future of the ocean from the Vortex queen.', 'The Japanese edition of the acclaimed aquatic sequel.', 'Ecco the Dolphin II (Tides of Time) pushes the Game Gear''s color palette to its limit. Experience a deep, narrative-driven adventure beneath the waves with improved mechanics and breathtaking visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ernie-els-golf-europe-enfrdeesit', 'Game Gear', 'Ernie Els Golf (Europe) (En,Fr,De,Es,It)', '1994', 'Sports', 'Tiertex', '1', 'Golf', 'Sports simulation (Golf).', 'Win the tournament on professional courses.', 'A refined and strategic portable golf simulation.', 'Ernie Els Golf offers a realistic approach to the links. Account for wind and slope as you compete in multiple modes, including match play and tournament, in this polished 8-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eternal-legend---eien-no-densetsu-english-v10', 'Game Gear', 'Eternal Legend - Eien no Densetsu (English v1.0)', '1991', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based RPG.', 'Seek the truth of the world and find the lost city.', 'English fan-translated version of the massive RPG.', 'Eternal Legend (English) allows Western fans to enjoy one of the system''s deepest RPGs. Explore a vast world and engage in strategic turn-based combat in this epic 8-bit quest, now fully playable in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eternal-legend---eien-no-densetsu-japan', 'Game Gear', 'Eternal Legend - Eien no Densetsu (Japan)', '1991', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based RPG.', 'Seek the truth of the world and find the lost city.', 'A Japanese exclusive RPG with a sprawling story.', 'Eternal Legend is a landmark title for the Game Gear. Featuring a detailed world map and traditional RPG mechanics, it tells an epic story of discovery and destiny with high-quality 8-bit production values.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('evander-holyfield-boxing-usa-europe', 'Game Gear', 'Evander Holyfield Boxing (USA, Europe)', '1992', 'Sports', 'Electronic Arts', '1', 'Boxing', 'Sports simulation (Boxing).', 'Knock out your opponents and win the world title.', 'Professional boxing with large, detailed sprites.', 'Evander Holyfield''s Real Deal Boxing brings the ring to your handheld. Master your timing and manage your stamina in this competitive 8-bit sim that features a deep career mode and smooth animation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('excellent-dizzy-collection-the-europe', 'Game Gear', 'Excellent Dizzy Collection, The (Europe)', '1993', 'Platform', 'Codemasters', '1', 'Cartoon', 'Puzzle platformer collection.', 'Solve puzzles and rescue the Yolkfolk in multiple games.', 'A three-game collection featuring the famous egg hero.', 'The Excellent Dizzy Collection includes Go! Dizzy Go!, Panic Dizzy, and Dizzy the Adventurer. It’s a perfect portable bundle of logic puzzles and charming platforming for the Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-15-strike-eagle-usa-europe', 'Game Gear', 'F-15 Strike Eagle (USA, Europe)', '1991', 'Simulation', 'MicroProse', '1', 'Flight Combat', 'Flight simulation.', 'Complete dangerous sorties in enemy territory.', 'A technical and intense modern jet fighter sim.', 'F-15 Strike Eagle tasks you with piloting the world''s most advanced jet. Use radar and tactical weapons to take down bogeys and ground targets in this impressive pseudo-3D flight simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-usa-europe', 'Game Gear', 'F1 (USA, Europe)', '1993', 'Racing', 'Domark', '1', 'Formula Racing', 'Behind-the-back racing.', 'Win the Formula One World Championship.', 'A fast and fluid F1 racing simulation.', 'F1 on Game Gear delivers high-speed open-wheel racing. Featuring real-world tracks and a technical pit-stop mechanic, it’s a challenging and responsive title for racing enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('faceball-2000-japan', 'Game Gear', 'Faceball 2000 (Japan)', '1992', 'Shooter', 'Xanth Software', '2', 'First-Person', 'First-person shooter (Smiley).', 'Tag all opponents and find the exit in the maze.', 'A pioneering first-person "Faceball" experience.', 'Faceball 2000 (Japan) is a technical marvel for the 8-bit era. Navigate 3D labyrinths and hunt down "smiley" enemies in this unique and early example of the FPS genre on a handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('factory-panic-europe', 'Game Gear', 'Factory Panic (Europe)', '1991', 'Action', 'Sega', '1', 'Arcade', 'Top-down puzzle action.', 'Move the crates and reach the exit of each level.', 'A strategic and brain-teasing puzzle game.', 'Factory Panic (known as Ganbare Gorubī! in Japan) challenges your logic. Help Gorby navigate through factories to feed the hungry in this charming and addictive portable puzzle-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-dizzy-europe-enfrdeesit', 'Game Gear', 'Fantastic Dizzy (Europe) (En,Fr,De,Es,It)', '1991', 'Platform', 'Codemasters', '1', 'Cartoon', 'Side-scrolling adventure.', 'Solve environmental puzzles to defeat the wizard Zaks.', 'The ultimate portable Dizzy platforming quest.', 'Fantastic Dizzy features a massive world to explore. Collect items, interact with the Yolkfolk, and solve clever logic puzzles in this beautifully drawn and heartwarming 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasy-zone-gear-usa-europe', 'Game Gear', 'Fantasy Zone Gear (USA, Europe)', '1991', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Defeat the invaders and earn money for upgrades.', 'A high-quality portable entry in the Fantasy Zone series.', 'Fantasy Zone Gear features the iconic Opa-Opa in a vibrant and colorful shooter. Buy weapons and engines in the shop to tackle quirky bosses in this polished handheld exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantasy-zone-gear-usa-europe-alt', 'Game Gear', 'Fantasy Zone Gear (USA, Europe) (Alt)', '1991', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Defeat the invaders and earn money for upgrades.', 'Alternate version of the vibrant portable shmup.', 'This alternate version of Fantasy Zone Gear maintains the frantic, candy-colored action the series is known for. It remains a standout title for the Game Gear''s color screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-special-usa-europe', 'Game Gear', 'Fatal Fury Special (USA, Europe)', '1994', 'Fighting', 'SNK', '2', 'Arcade', 'One-on-one fighting game.', 'Win the tournament to prove you are the best.', 'A technical and impressive port of the SNK hit.', 'Fatal Fury Special brings the heat to the Game Gear. Featuring a diverse roster and the series'' signature two-plane combat system, it is one of the most competent fighters on 8-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-international-soccer-japan', 'Game Gear', 'FIFA International Soccer (Japan)', '1994', 'Sports', 'Electronic Arts', '2', 'Soccer', 'Sports simulation (Soccer).', 'Lead your national team to international glory.', 'The Japanese edition of the worldwide soccer hit.', 'FIFA International Soccer brings the pitch to your pocket. Master the isometric perspective and strategic plays in this detailed 8-bit simulation of the beautiful game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-international-soccer-usa-europe', 'Game Gear', 'FIFA International Soccer (USA, Europe)', '1994', 'Sports', 'Electronic Arts', '2', 'Soccer', 'Sports simulation (Soccer).', 'Lead your national team to international glory.', 'The definitive international version of FIFA 94.', 'FIFA International Soccer for Game Gear features smooth animation and a variety of modes. Experience the tension of international competition in this polished 8-bit portable sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-soccer-96-usa-europe-enfrdees', 'Game Gear', 'FIFA Soccer 96 (USA, Europe) (En,Fr,De,Es)', '1995', 'Sports', 'Electronic Arts', '2', 'Soccer', 'Sports simulation (Soccer).', 'Win the championship in the 1996 soccer season.', 'The late-release update to the FIFA series.', 'FIFA Soccer 96 offers updated rosters and refined 8-bit gameplay. Compete for the title with improved AI and more tactical options in this comprehensive handheld soccer simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('foreman-for-real-usa-europe', 'Game Gear', 'Foreman for Real (USA, Europe)', '1995', 'Sports', 'Software Creations', '1', 'Boxing', 'Sports simulation (Boxing).', 'Knock out rivals to become the champion of the world.', 'A gritty and hard-hitting boxing simulation.', 'Foreman for Real features large sprites and a behind-the-back perspective. Master the art of the jab and hook in this intense sports title that emphasizes timing and ring strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frank-thomas-big-hurt-baseball-usa', 'Game Gear', 'Frank Thomas Big Hurt Baseball (USA)', '1995', 'Sports', 'Accolade', '1', 'Baseball', 'Sports simulation (Baseball).', 'Lead your team to victory in a full MLB season.', 'A technical baseball sim endorsed by "The Big Hurt."', 'Frank Thomas Big Hurt Baseball features realistic pitching and batting physics. With multiple modes and professional stats, it provides a deep and rewarding baseball experience for Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fray---shugyou-hen-japan', 'Game Gear', 'Fray - Shugyou Hen (Japan)', '1991', 'Action', 'Sega', '1', 'Adventure', 'Action RPG / Top-down.', 'Complete your training and defeat the dark forces.', 'A vibrant Japanese exclusive anime-style RPG.', 'Fray: Shugyou Hen features high-energy combat and beautiful character portraits. Explore a fantasy world and master magical spells in this polished 8-bit adventure that pushes the Game Gear''s color palette.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fred-couples-golf-japan', 'Game Gear', 'Fred Couples'' Golf (Japan)', '1993', 'Sports', 'Sega', '1', 'Golf', 'Sports simulation (Golf).', 'Win the tour and master the professional links.', 'The Japanese edition of the pro-endorsed golf sim.', 'Fred Couples'' Golf offers a deep and strategic take on the sport. Featuring realistic wind and terrain physics, it provides a high-quality 8-bit simulation for golf enthusiasts on the move.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fred-couples-golf-usa', 'Game Gear', 'Fred Couples'' Golf (USA)', '1993', 'Sports', 'Sega', '1', 'Golf', 'Sports simulation (Golf).', 'Win the tour and master the professional links.', 'A refined and strategic portable golf simulation.', 'Master the greens in Fred Couples'' Golf. With smooth controls and detailed course layouts, this North American release is one of the most mechanically sound sports titles on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger-usa-proto', 'Game Gear', 'Frogger (USA) (Proto)', '1997', 'Action', 'Konami', '1', 'Arcade', 'Fixed-screen arcade.', 'Guide the frogs home while avoiding traffic and water.', 'An unreleased prototype of the arcade legend.', 'This Frogger Prototype is a rare look at a lost port. Experience the classic "hop-and-dodge" gameplay on the Game Gear, featuring vibrant colors and the iconic high-stakes arcade loop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('from-tv-animation---slam-dunk---shouri-e-no-starting-5-japan', 'Game Gear', 'From TV Animation - Slam Dunk - Shouri e no Starting 5 (Japan)', '1994', 'Sports', 'Bandai', '2', 'Basketball', 'Sports simulation (Basketball).', 'Lead Shohoku to victory in the tournament.', 'A Japanese exclusive based on the legendary anime.', 'Slam Dunk: Shouri e no Starting 5 features cinematic action and RPG-style menu choices. Experience the intensity of the manga on your handheld with large, expressive character sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('g-loc-air-battle-japan', 'Game Gear', 'G-LOC Air Battle (Japan)', '1990', 'Shooter', 'Sega', '1', 'Flight Combat', 'Behind-the-back rail shooter.', 'Engage in high-speed dogfights and destroy targets.', 'Intense aerial combat based on the After Burner tech.', 'G-LOC Air Battle delivers 360-degree dogfighting action. Use your lock-on missiles to clear the skies in this technically impressive 8-bit port that captures the speed of the arcade.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('g-loc-air-battle-japan-v11', 'Game Gear', 'G-LOC Air Battle (Japan) (v1.1)', '1990', 'Shooter', 'Sega', '1', 'Flight Combat', 'Behind-the-back rail shooter.', 'Engage in high-speed dogfights and destroy targets.', 'Updated Japanese version of the jet-combat hit.', 'This v1.1 of G-LOC features refined controls and minor bug fixes. Experience the thrill of modern aerial warfare with smooth scaling and high-energy 8-bit sound.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('g-loc-air-battle-usa-europe', 'Game Gear', 'G-LOC Air Battle (USA, Europe)', '1990', 'Shooter', 'Sega', '1', 'Flight Combat', 'Behind-the-back rail shooter.', 'Engage in high-speed dogfights and destroy targets.', 'The international release of the high-speed air battle.', 'Pilot a fighter jet in the Western version of G-LOC. Battle through multiple missions, managing your fuel and weapons in this fast-paced and immersive handheld shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaga-91-japan', 'Game Gear', 'Galaga ''91 (Japan)', '1991', 'Shooter', 'Namco', '1', 'Arcade', 'Fixed-screen shoot ''em up.', 'Destroy the invading Galaga forces.', 'A vibrant portable update of the arcade classic.', 'Galaga ''91 (also known as Galaga 2) brings the bug-blasting action to Game Gear. Featuring new boss patterns and power-ups, it’s a perfect color conversion of the legendary shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gamble-panic-japan', 'Game Gear', 'Gamble Panic (Japan)', '1993', 'Casino', 'Sega', '1', 'Gambling', 'Gambling / Board game.', 'Win big in various Japanese gambling challenges.', 'A colorful Japanese exclusive betting sim.', 'Gamble Panic features a variety of casino-style games and betting mechanics. It captures the high-energy atmosphere of Japanese arcades with bright visuals and engaging mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gambler-jikochuushinha-japan', 'Game Gear', 'Gambler Jikochuushinha (Japan)', '1993', 'Casino', 'Sega', '1', 'Gambling', 'Mahjong simulation.', 'Defeat quirky opponents in professional Mahjong.', 'A Japanese exclusive based on the comedy manga.', 'Gambler Jikochuushinha offers a fun and character-driven take on Mahjong. Use strategy and luck to outplay hilarious rivals in this deep 8-bit simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-gorby!-japan', 'Game Gear', 'Ganbare Gorby! (Japan)', '1991', 'Action', 'Sega', '1', 'Arcade', 'Top-down puzzle action.', 'Move the crates and reach the exit of each level.', 'The Japanese version of Factory Panic.', 'Ganbare Gorby! features the character Gorby in a quest to deliver food. Solve challenging grid-based puzzles by manipulating machinery in this charming and addictive portable title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garfield---caught-in-the-act-usa', 'Game Gear', 'Garfield - Caught in the Act (USA)', '1995', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Battle your way through the TV world to get home.', 'A visually stunning adventure starring the lazy cat.', 'Garfield: Caught in the Act features incredible animation and varied levels based on TV genres. Use Garfield’s humor and items to navigate this high-quality 8-bit handheld quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garou-densetsu-special-japan', 'Game Gear', 'Garou Densetsu Special (Japan)', '1994', 'Fighting', 'SNK', '2', 'Arcade', 'One-on-one fighting game.', 'Win the tournament to prove you are the best.', 'The original Japanese version of Fatal Fury Special.', 'Garou Densetsu Special is a masterpiece of handheld fighting. Featuring a huge roster and fluid combat mechanics, it stands as one of the best 1v1 brawlers on the Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gear-stadium-japan', 'Game Gear', 'Gear Stadium (Japan)', '1991', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Lead your team to the championship title.', 'A classic Namco-style portable baseball sim.', 'Gear Stadium offers fast-paced, arcade-style baseball action. With its cute "chibi" character sprites and simple controls, it’s one of the most accessible and fun sports games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gear-stadium-heiseiban-japan', 'Game Gear', 'Gear Stadium Heiseiban (Japan)', '1991', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Lead your team to the championship title.', 'Updated "modern" version of the Gear Stadium hit.', 'Gear Stadium Heiseiban features updated rosters and refined graphics. Experience the classic baseball gameplay with a more contemporary feel in this Japanese exclusive sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gear-works-usa-europe', 'Game Gear', 'Gear Works (USA, Europe)', '1993', 'Puzzle', 'Sega', '1', 'Arcade', 'Isometric puzzle game.', 'Connect the gears to power the machinery.', 'A brain-teasing and unique physics puzzle.', 'Gear Works tasks you with fitting various sized gears onto a board to reach a goal. It’s a challenging logic game that requires foresight and planning, perfect for portable puzzle fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('george-foremans-ko-boxing-usa-europe', 'Game Gear', 'George Foreman''s KO Boxing (USA, Europe)', '1992', 'Sports', 'Electronic Arts', '2', 'Boxing', 'Sports simulation (Boxing).', 'Knock out rivals to become the champion.', 'A gritty and hard-hitting 8-bit boxing sim.', 'George Foreman''s KO Boxing features large, detailed sprites and an intense behind-the-back perspective. Master your defense and power punches to climb the rankings and win the belt.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gg-aleste-japan', 'Game Gear', 'GG Aleste (Japan)', '1991', 'Shooter', 'Compile', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Destroy the enemy fleet and the supercomputer.', 'A technical marvel and one of the system''s best.', 'GG Aleste is a legendary shmup known for its blistering speed and weapon variety. Developed by Compile, it features some of the best 8-bit visuals and music ever produced for a handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gg-doraemon---noranosuke-no-yabou-japan', 'Game Gear', 'GG Doraemon - Noranosuke no Yabou (Japan)', '1993', 'Adventure', 'Sega', '1', 'Anime', 'Side-scrolling platformer.', 'Stop Noranosuke and save the neighborhood.', 'A colorful Japanese exclusive starring Doraemon.', 'GG Doraemon: Noranosuke no Yabou features the gadget-filled world of the blue cat. Use unique items to navigate levels and defeat enemies in this charming and vibrant 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gg-portrait---pai-chen-japan', 'Game Gear', 'GG Portrait - Pai Chen (Japan)', '1994', 'Simulation', 'Sega', '1', 'Portrait', 'Visualizer / Mini-game.', 'Interact with Pai Chen from Virtua Fighter.', 'A unique 8-bit digital portrait experience.', 'GG Portrait: Pai Chen allows fans to interact with the VF heroine. Featuring high-quality 8-bit art and simple mini-games, it serves as a collectible showcase for fans of the fighting series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gg-portrait---yuuki-akira-japan', 'Game Gear', 'GG Portrait - Yuuki Akira (Japan)', '1994', 'Simulation', 'Sega', '1', 'Portrait', 'Visualizer / Mini-game.', 'Interact with Akira Yuki from Virtua Fighter.', 'A unique 8-bit digital portrait experience.', 'GG Portrait: Yuuki Akira features the protagonist of Virtua Fighter. Explore detailed artwork and voice clips in this interesting hardware-pushing "digital merchandise" title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gg-shinobi-ii-the---the-silent-fury-japan', 'Game Gear', 'GG Shinobi II, The - The Silent Fury (Japan)', '1992', 'Action', 'Sega', '1', 'Ninja', 'Side-scrolling action platformer.', 'Recover the five sacred crystals to save the world.', 'The pinnacle of ninja action on Game Gear.', 'The Silent Fury (Shinobi II) features five playable ninjas, each with unique powers. Explore non-linear stages and master complex platforming in this must-play 8-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gg-shinobi-the-europe', 'Game Gear', 'GG Shinobi, The (Europe)', '1991', 'Action', 'Sega', '1', 'Ninja', 'Side-scrolling action platformer.', 'Defeat the Neo Zeed empire and rescue the hostages.', 'A high-quality ninja quest for the Western market.', 'The GG Shinobi is a legendary handheld exclusive. Navigate through themed levels like the forest and the city, utilizing magic and stealth in this incredibly polished and atmospheric title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gg-shinobi-the-japan', 'Game Gear', 'GG Shinobi, The (Japan)', '1991', 'Action', 'Sega', '1', 'Ninja', 'Side-scrolling action platformer.', 'Defeat the Neo Zeed empire and rescue the hostages.', 'The Japanese original of the iconic ninja game.', 'GG Shinobi (Japan) features tight controls and a legendary soundtrack by Yuzo Koshiro. It is widely considered one of the finest games in the entire 8-bit Sega library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('godzilla---kaijuu-daishingeki-japan', 'Game Gear', 'Godzilla - Kaijuu Daishingeki (Japan)', '1993', 'Action', 'Compile', '1', 'Kaiju', 'Side-scrolling strategy action.', 'Command Godzilla and Mothra to defend Japan.', 'A unique blend of strategy and kaiju combat.', 'Godzilla: Kaijuu Daishingeki features epic monster battles. Move your units across a map and engage in 2D action segments to defeat Gigan and King Ghidorah in this impressive Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gp-rider-japan', 'Game Gear', 'GP Rider (Japan)', '1992', 'Racing', 'Sega', '1', 'Motorcycle', 'Behind-the-back racing.', 'Outpace the competition and cross the finish line.', 'A high-speed motorcycle racing port.', 'GP Rider (Japan) brings the arcade''s 1v1 racing tension to the Game Gear. Featuring smooth scaling and a detailed cockpit view, it’s a technical showcase of handheld racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gp-rider-usa-europe', 'Game Gear', 'GP Rider (USA, Europe)', '1992', 'Racing', 'Sega', '1', 'Motorcycle', 'Behind-the-back racing.', 'Outpace the competition and cross the finish line.', 'International release of the motorcycle racer.', 'Compete in high-stakes bike races in GP Rider. Master the corners and manage your turbo to defeat AI rivals in this fast-paced and visually impressive 8-bit portable title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('greendog-usa-europe', 'Game Gear', 'Greendog (USA, Europe)', '1992', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Use your frisbee to survive the surfing planets.', 'A visually stunning and quirky action adventure.', 'Greendog features some of the most detailed parallax scrolling on the system. Help the laid-back surfer survive dangerous levels using his trusty frisbee in this colorful and unique 8-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('griffin-japan', 'Game Gear', 'Griffin (Japan)', '1991', 'Shooter', 'Sega', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Fly through enemy territory and destroy the core.', 'A Japanese exclusive sci-fi military shooter.', 'Griffin delivers intense aerial combat with a military theme. Maneuver through waves of enemy jets and tanks in this fast-paced 8-bit shmup that rewards quick reflexes and precise shooting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunstar-heroes-japan', 'Game Gear', 'Gunstar Heroes (Japan)', '1991', 'Action', 'Treasure', '2', 'Run and Gun', 'Side-scrolling run and gun.', 'Defeat the Empire and recover the powerful gems.', 'A technical masterpiece and miracle port for Game Gear.', 'Gunstar Heroes is an 8-bit wonder. Featuring incredible boss fights, weapon combining, and high-speed action, it brings Treasure’s legendary gameplay to the handheld with surprising fidelity and color.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('halley-wars-japan', 'Game Gear', 'Halley Wars (Japan)', '1991', 'Shooter', 'Taito', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Destroy the Halley''s Comet invaders.', 'The original Japanese version of the sci-fi shooter.', 'Halley Wars (Japan) delivers classic arcade-style shooting. Defend Earth from a celestial invasion across multiple space-themed stages in this fast-paced and visually clean 8-bit shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('halley-wars-usa-europe', 'Game Gear', 'Halley Wars (USA, Europe)', '1991', 'Shooter', 'Taito', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Destroy the Halley''s Comet invaders.', 'The international release of the high-energy space shooter.', 'Experience the intensity of Halley Wars. Maneuver through asteroid fields and mechanical fortresses to eliminate the alien threat in this polished and challenging portable shooting classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('head-buster-japan', 'Game Gear', 'Head Buster (Japan)', '1990', 'Action', 'Sega', '1', 'Arcade', 'Turn-based strategy.', 'Command a team of robots in tactical combat.', 'A Japanese exclusive strategy game with customizable mechs.', 'Head Buster tasks you with managing a squad of combat robots. Buy parts, upgrade weapons, and use tactical positioning to win skirmishes in this deep and visually distinct 8-bit strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('head-buster-japan-en-by-chris-covell-v10', 'Game Gear', 'Head Buster (Japan) [En by Chris Covell v1.0]', '1990', 'Action', 'Sega', '1', 'Arcade', 'Turn-based strategy.', 'Command a team of robots in tactical combat.', 'English fan-translation of the robot strategy game.', 'This localized version of Head Buster allows Western players to understand the complex part-management and strategic dialogue of this unique Japanese mecha-combat simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heavy-weight-champ-japan', 'Game Gear', 'Heavy Weight Champ (Japan)', '1991', 'Fighting', 'Sega', '2', 'Boxing', 'One-on-one boxing.', 'Knock out your opponent to win the title.', 'A portable update of Sega''s historic boxing brand.', 'Heavy Weight Champ features large, detailed boxers and intense 1v1 action. Master your timing and defense to climb the ranks in this high-energy 8-bit handheld sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('home-alone-usa-europe', 'Game Gear', 'Home Alone (USA, Europe)', '1991', 'Action', 'THQ', '1', 'Movie', 'Side-scrolling platformer / Puzzle.', 'Trap the burglars and protect your home.', 'A creative defensive action game based on the movie.', 'Home Alone tasks Kevin McCallister with setting traps to stop Harry and Marv. Collect household items to craft weapons and survive the night in this charming movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honoo-no-toukyuuji---dodge-danpei-japan', 'Game Gear', 'Honoo no Toukyuuji - Dodge Danpei (Japan)', '1992', 'Sports', 'Bandai', '2', 'Dodgeball', 'Sports simulation (Dodgeball).', 'Defeat rival teams in high-stakes dodgeball matches.', 'An intense Japanese exclusive based on the anime.', 'Dodge Danpei brings explosive dodgeball action to the Game Gear. Use special "flame" throws and team tactics to win the tournament in this vibrant and fast-paced sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hook-usa-europe', 'Game Gear', 'Hook (USA, Europe)', '1992', 'Action', 'Ubisoft', '1', 'Movie', 'Side-scrolling platformer.', 'Rescue the children from Captain Hook.', 'A cinematic adventure based on the Peter Pan film.', 'Hook features beautiful 8-bit graphics and diverse levels. Play as Peter Pan, flying and fighting through Neverland to reclaim your family in this polished and atmospheric handheld quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hurricanes-usa-europe', 'Game Gear', 'Hurricanes (USA, Europe)', '1994', 'Sports', 'U.S. Gold', '2', 'Soccer', 'Side-scrolling platformer.', 'Win the world soccer tournament across various levels.', 'A soccer-themed platformer based on the cartoon.', 'Hurricanes features the soccer stars in an adventure that blends sports and platforming. Use your ball to defeat enemies and solve puzzles in this colorful European handheld exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyokkori-hyoutan-jima---hyoutan-jima-no-daikoukai-japan', 'Game Gear', 'Hyokkori Hyoutan Jima - Hyoutan Jima no Daikoukai (Japan)', '1992', 'Adventure', 'Sega', '1', 'Anime', 'Side-scrolling platformer.', 'Navigate the floating island and solve its mysteries.', 'A Japanese exclusive based on the puppet show.', 'Hyokkori Hyoutan Jima features a unique art style and charming characters. Explore the sea and various islands in this whimsical and family-friendly 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyper-pro-yakyuu-92-japan', 'Game Gear', 'Hyper Pro Yakyuu ''92 (Japan)', '1992', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Win the Japanese league championship.', 'A detailed and professional 1992 baseball sim.', 'Hyper Pro Yakyuu ''92 offers deep rosters and realistic 8-bit baseball mechanics. Perfect your pitching and hitting to lead your team to victory in this polished Japanese sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ichidant~r-gg-japan', 'Game Gear', 'Ichidant~R GG (Japan)', '1993', 'Puzzle', 'Sega', '1', 'Arcade', 'Mini-game collection.', 'Complete a series of wacky challenges to win.', 'A portable version of the iconic puzzle-arcade hit.', 'Ichidant~R GG features hilarious and fast-paced mini-games. Test your reflexes and logic in this vibrant Japanese exclusive that perfectly captures Sega’s quirky arcade spirit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('in-the-wake-of-vampire-japan', 'Game Gear', 'In the Wake of Vampire (Japan)', '1992', 'Action', 'Sims', '1', 'Horror', 'Side-scrolling action platformer.', 'Hunt Dracula and end the vampire curse.', 'The Japanese version of the gothic classic Master of Darkness.', 'In the Wake of Vampire is Game Gear’s answer to Castlevania. Use daggers, axes, and magic to fight through 19th-century London in this atmospheric and high-quality horror-action quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-crash-dummies-the-usa-europe', 'Game Gear', 'Incredible Crash Dummies, The (USA, Europe)', '1994', 'Action', 'LJN', '1', 'Platform', 'Side-scrolling platformer.', 'Survive dangerous crash tests and reach the goal.', 'A quirky action game based on the popular toys.', 'The Incredible Crash Dummies features unique physics and humor. Help Slick and Spin navigate through hazard-filled levels in this vibrant and surprisingly challenging 8-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-hulk-the-usa-europe', 'Game Gear', 'Incredible Hulk, The (USA, Europe)', '1994', 'Action', 'U.S. Gold', '1', 'Superhero', 'Side-scrolling action.', 'Stop the Leader and his gamma-powered army.', 'A powerful brawler starring Marvel’s Green Goliath.', 'The Incredible Hulk features large sprites and destructive gameplay. Use the Hulk’s strength to smash through walls and enemies in this visually impressive and difficult handheld action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-and-the-last-crusade-usa-europe', 'Game Gear', 'Indiana Jones and the Last Crusade (USA, Europe)', '1992', 'Action', 'Tiertex', '1', 'Adventure', 'Side-scrolling platformer.', 'Find the Holy Grail and rescue your father.', 'A cinematic adventure based on the classic film.', 'Indiana Jones and the Last Crusade features whip-cracking action and iconic locations. Solve puzzles and fight Nazis in this faithful 8-bit recreation of Indy''s most famous quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iron-man-x-o-manowar-in-heavy-metal-usa-europe', 'Game Gear', 'Iron Man X-O Manowar in Heavy Metal (USA, Europe)', '1996', 'Action', 'Realtime Associates', '1', 'Superhero', 'Side-scrolling shooter.', 'Stop the nuclear threat in a futuristic armor suit.', 'A high-octane comic book crossover action game.', 'Iron Man X-O Manowar features heavy firepower and jetpack flight. Blast through high-tech facilities and defeat massive bosses in this intense and visually busy 8-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itchy-&-scratchy-game-the-europe', 'Game Gear', 'Itchy & Scratchy Game, The (Europe)', '1992', 'Platform', 'Bits Studios', '1', 'Cartoon', 'Side-scrolling action.', 'Torture each other across various cartoon levels.', 'A violent and humorous cartoon brawler.', 'The Itchy & Scratchy Game brings the "show within a show" to the Game Gear. Engage in slapstick violence and use wacky weapons in this colorful European-exclusive platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-gg-pro-striker-94-japan', 'Game Gear', 'J.League GG Pro Striker ''94 (Japan)', '1994', 'Sports', 'Sega', '2', 'Soccer', 'Sports simulation (Soccer).', 'Win the J.League championship title.', 'A professional 1994 Japanese soccer simulation.', 'J.League GG Pro Striker ''94 features authentic teams and fast-paced 8-bit soccer. Master the isometric field and lead your club to the top of the Japanese standings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-soccer---dream-eleven-japan', 'Game Gear', 'J.League Soccer - Dream Eleven (Japan)', '1993', 'Sports', 'Sega', '2', 'Soccer', 'Sports simulation (Soccer).', 'Manage and play your way to the top of the J.League.', 'A strategic and action-oriented soccer sim.', 'J.League Soccer: Dream Eleven combines team management with arcade soccer action. Build your dream team and compete in the national league in this polished Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-bond-007---the-duel-europe', 'Game Gear', 'James Bond 007 - The Duel (Europe)', '1993', 'Action', 'Domark', '1', 'Action', 'Side-scrolling action shooter.', 'Infiltrate enemy bases and stop the organization.', 'A cinematic 007 adventure for the Game Gear.', 'James Bond 007: The Duel features gadget-based combat and explosive levels. Rescue hostages and defeat iconic villains in this polished 8-bit shooter that captures the Bond atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-pond-3---operation-starfi5h-europe', 'Game Gear', 'James Pond 3 - Operation Starfi5h (Europe)', '1993', 'Platform', 'Vectordean', '1', 'Platform', 'Side-scrolling platformer.', 'Stop the evil Dr. Maybe on the moon.', 'A fast and fluid underwater (and space) adventure.', 'James Pond 3 features the secret agent fish in a massive quest. Use your stretching abilities and gadgets to navigate through creative levels in this vibrant European platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-pond-ii---codename-robocod-usa-europe', 'Game Gear', 'James Pond II - Codename RoboCod (USA, Europe)', '1991', 'Platform', 'Millennium', '1', 'Platform', 'Side-scrolling platformer.', 'Rescue the captured penguins and stop Dr. Maybe.', 'A classic "stretchy" platformer with amazing 8-bit art.', 'James Pond II: Codename RoboCod is a handheld masterpiece. Stretch your robotic suit to reach high platforms and explore colorful, toy-themed worlds in this charming and polished quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!---sports-edition-usa-europe', 'Game Gear', 'Jeopardy! - Sports Edition (USA, Europe)', '1991', 'Trivia', 'GameTek', '2', 'Quiz', 'Quiz / Trivia.', 'Answer sports-themed questions to win the game.', 'A specialized edition of the famous TV game show.', 'Jeopardy! Sports Edition tests your knowledge of athletic history. Compete against the computer or friends in this detailed 8-bit simulation of the iconic trivia program.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!-usa-europe', 'Game Gear', 'Jeopardy! (USA, Europe)', '1991', 'Trivia', 'GameTek', '2', 'Quiz', 'Quiz / Trivia.', 'Provide the question to the given answers.', 'A faithful digital version of the hit TV show.', 'Jeopardy! on Game Gear features thousands of clues across various categories. Perfect for on-the-go brain training, this 8-bit simulation captures all the tension of the television original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-montanas-football-japan', 'Game Gear', 'Joe Montana''s Football (Japan)', '1991', 'Sports', 'Sega', '2', 'Football', 'Sports simulation (Football).', 'Lead your team to the championship with Joe Montana.', 'The Japanese edition of the pro-endorsed football sim.', 'Joe Montana''s Football offers a strategic take on the gridiron. Call the plays and execute precision passes in this polished 8-bit simulation of American football.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-montanas-football-usa-europe', 'Game Gear', 'Joe Montana''s Football (USA, Europe)', '1991', 'Sports', 'Sega', '2', 'Football', 'Sports simulation (Football).', 'Lead your team to the championship with Joe Montana.', 'A classic and accessible 8-bit football experience.', 'Experience the excitement of the NFL on the go. Joe Montana''s Football features smooth animation and multiple modes, providing a solid sports challenge for handheld gamers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('journey-from-darkness---strider-returns-usa-europe', 'Game Gear', 'Journey from Darkness - Strider Returns (USA, Europe)', '1992', 'Action', 'U.S. Gold', '1', 'Action', 'Side-scrolling action platformer.', 'Recover the secret documents and defeat the empire.', 'A Western-developed sequel to the Strider legend.', 'Journey from Darkness: Strider Returns features the iconic assassin in a new mission. Use your climbing skills and Cypher blade to battle through robotic threats in this challenging 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('judge-dredd-usa-europe', 'Game Gear', 'Judge Dredd (USA, Europe)', '1995', 'Action', 'Raise', '1', 'Comic', 'Side-scrolling action shooter.', 'Bring law to the streets of Mega-City One.', 'A gritty and difficult shooter based on the comics.', 'Judge Dredd features high-tech weaponry and atmospheric 8-bit visuals. Use your Lawgiver to arrest or eliminate criminals in this intense and action-packed handheld movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('junction-usa-europe', 'Game Gear', 'Junction (USA, Europe)', '1993', 'Action', 'Microids', '1', 'Platform', 'Isometric puzzle.', 'Guide a ball through a sliding tile maze.', 'A challenging and unique path-making puzzle game.', 'Junction tests your spatial reasoning as you slide tiles to create a safe path for a moving ball. With its clean graphics and increasing difficulty, it’s a brain-teasing gem for portable puzzle fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-book-the-europe', 'Game Gear', 'Jungle Book, The (Europe)', '1994', 'Platform', 'Virgin Interactive', '1', 'Movie', 'Side-scrolling platformer.', 'Collect gems and defeat Shere Khan to stay in the jungle.', 'A colorful Disney adventure with amazing animation.', 'The Jungle Book (Europe) brings Mowgli’s quest to your handheld. Swing on vines and throw fruit at enemies in this visually lush 8-bit platformer that captures the heart of the movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-book-the-usa', 'Game Gear', 'Jungle Book, The (USA)', '1994', 'Platform', 'Virgin Interactive', '1', 'Movie', 'Side-scrolling platformer.', 'Collect gems and defeat Shere Khan to stay in the jungle.', 'The North American release of the Disney classic.', 'Experience the high-energy platforming of Mowgli’s adventure in the US version. Featuring smooth controls and detailed sprites, it remains one of the most polished movie tie-ins on Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-europe', 'Game Gear', 'Jurassic Park (Europe)', '1993', 'Action', 'Ocean Software', '1', 'Movie', 'Side-scrolling action platformer.', 'Restore power to the park and survive the dinosaurs.', 'An intense and cinematic dinosaur survival game.', 'Jurassic Park (Europe) features impressive vehicle stages and challenging foot missions. Battle Velociraptors and the T-Rex in this action-packed 8-bit adventure through Isla Nublar.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-japan', 'Game Gear', 'Jurassic Park (Japan)', '1993', 'Action', 'Ocean Software', '1', 'Movie', 'Side-scrolling action platformer.', 'Restore power to the park and survive the dinosaurs.', 'The Japanese edition of the high-stakes dino shooter.', 'Experience the thrill of Jurassic Park on the go. This Japanese version highlights the system’s color depth with detailed jungle environments and massive, prehistoric boss encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaitou-saint-tale-japan', 'Game Gear', 'Kaitou Saint Tale (Japan)', '1995', 'Adventure', 'Bandai', '1', 'Anime', 'Adventure / Puzzle.', 'Use magic to reclaim stolen items and help people.', 'A Japanese exclusive based on the magical girl anime.', 'Kaitou Saint Tale features beautiful character art and story-driven puzzles. Play as Meimi (Saint Tail) and use your magic tricks to outsmart the police in this charming 8-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawasaki-superbike-challenge-usa', 'Game Gear', 'Kawasaki Superbike Challenge (USA)', '1994', 'Racing', 'Teque Software', '1', 'Motorcycle', 'Behind-the-back racing.', 'Win the world championship on official Kawasaki bikes.', 'A high-speed, technical motorcycle racing sim.', 'Kawasaki Superbike Challenge offers smooth scaling and realistic handling. Compete on global tracks and manage your bike''s performance in this technically ambitious 8-bit portable racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kenyuu-densetsu-yaiba-japan', 'Game Gear', 'Kenyuu Densetsu Yaiba (Japan)', '1994', 'Action', 'Bandai', '1', 'Anime', 'Side-scrolling action.', 'Defeat Onimaru and his demonic army.', 'A Japanese exclusive based on the popular manga.', 'Kenyuu Densetsu Yaiba brings intense sword combat to the Game Gear. Use legendary blades and special moves to defeat mythical enemies in this vibrant and fast-paced 8-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kick-&-rush-japan', 'Game Gear', 'Kick & Rush (Japan)', '1993', 'Sports', 'Sega', '2', 'Soccer', 'Sports simulation (Soccer).', 'Win the championship in a fast-paced soccer league.', 'A quirky Japanese exclusive arcade soccer game.', 'Kick & Rush offers a fun, high-energy take on the beautiful game. With fast players and simple controls, it''s designed for quick matches and portable sports fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kinetic-connection-japan', 'Game Gear', 'Kinetic Connection (Japan)', '1992', 'Puzzle', 'Sega', '1', 'Arcade', 'Sliding tile puzzle.', 'Reassemble the photograph before time runs out.', 'A relaxing and visual Japanese logic puzzle.', 'Kinetic Connection challenges your observation skills. Rotate and slide pieces to complete beautiful images in this polished and addictive 8-bit handheld puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kishin-douji-zenki-japan', 'Game Gear', 'Kishin Douji Zenki (Japan)', '1995', 'Action', 'Bandai', '1', 'Anime', 'Side-scrolling action.', 'Help Zenki defeat the Seeds of Possession.', 'A Japanese exclusive based on the supernatural anime.', 'Kishin Douji Zenki features impressive combat mechanics and transformations. Battle demonic spirits and protect the world in this visually striking and intense 8-bit action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klax-usa-europe', 'Game Gear', 'Klax (USA, Europe)', '1991', 'Puzzle', 'Tengen', '1', 'Arcade', 'Falling block puzzle.', 'Catch colored tiles and align them in rows.', 'The portable version of the classic arcade puzzler.', 'Klax is a game of logic and reflexes. Arrange tiles of the same color into horizontal, vertical, or diagonal lines in this addictive and perfectly-scaled 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('krustys-fun-house-usa-europe', 'Game Gear', 'Krusty''s Fun House (USA, Europe)', '1991', 'Puzzle', 'Tengen', '1', 'Arcade', 'Side-scrolling puzzle platformer.', 'Clear the fun house of rodents by solving puzzles.', 'A creative Simpsons adventure focused on logic.', 'Krusty''s Fun House tasks you with guiding rats into extermination machines. Use various items to build paths in this clever and colorful 8-bit puzzle-platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuni-chan-no-game-tengoku-japan', 'Game Gear', 'Kuni-chan no Game Tengoku (Japan)', '1994', 'Action', 'Namco', '1', 'Comedy', 'Board game / Mini-games.', 'Win against Kuni-chan in various digital board games.', 'A Japanese exclusive featuring a popular variety star.', 'Kuni-chan no Game Tengoku is a vibrant collection of mini-games and board game simulations. It’s a lighthearted and fun title that showcases the Game Gear''s colorful personality.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuni-chan-no-game-tengoku-part-2-japan', 'Game Gear', 'Kuni-chan no Game Tengoku Part 2 (Japan)', '1995', 'Action', 'Namco', '1', 'Comedy', 'Board game / Mini-games.', 'Compete in even more wacky challenges and games.', 'The sequel to the Japanese variety game collection.', 'Kuni-chan no Game Tengoku Part 2 expands on the original with more variety and better graphics. Perfect for short bursts of play, it’s a charming piece of Japanese handheld history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('land-of-illusion-starring-mickey-mouse-usa-europe', 'Game Gear', 'Land of Illusion Starring Mickey Mouse (USA, Europe)', '1993', 'Platform', 'Sega', '1', 'Platform', 'Side-scrolling platformer.', 'Reclaim the "Good Magic" from the Phantom Castle.', 'A legendary masterpiece of 8-bit level design.', 'Land of Illusion is one of Mickey''s finest hours. Featuring creative items and stunning environments, guide Mickey through a fantasy world in this technically brilliant and charming classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('last-action-hero-usa-europe', 'Game Gear', 'Last Action Hero (USA, Europe)', '1994', 'Action', 'Sony Imagesoft', '1', 'Movie', 'Side-scrolling beat ''em up.', 'Fight your way through the movie world.', 'A gritty action game based on the Schwarzenegger film.', 'Last Action Hero features tough urban combat and vehicle stages. Use Danny’s movie knowledge and Jack’s brawn to defeat the villains in this atmospheric handheld brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-illusion-starring-mickey-mouse-usa-europe', 'Game Gear', 'Legend of Illusion Starring Mickey Mouse (USA, Europe)', '1994', 'Platform', 'Sega', '1', 'Platform', 'Side-scrolling platformer.', 'Find the lost book and stop the evil queen.', 'The stunning final chapter of the Illusion trilogy.', 'Legend of Illusion features beautiful graphics and a focus on story and item collection. It''s a technical showcase for the Game Gear and a must-play for Disney fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-usa-europe', 'Game Gear', 'Lemmings (USA, Europe)', '1992', 'Puzzle', 'DMA Design', '1', 'Puzzle', 'Strategy puzzle.', 'Guide the helpless Lemmings to the exit of each level.', 'The definitive portable version of the puzzle hit.', 'Lemmings on Game Gear captures the addictive "save-them-all" gameplay perfectly. Assign skills to your lemmings to navigate deadly traps in this deep and challenging 8-bit port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-usa-europe-beta', 'Game Gear', 'Lemmings (USA, Europe) (Beta)', '1992', 'Puzzle', 'DMA Design', '1', 'Puzzle', 'Strategy puzzle.', 'Guide the helpless Lemmings to the exit of each level.', 'Beta version of the iconic portable puzzle-strategy game.', 'This Lemmings Beta offers a look at the early development of the handheld port. Test the interface and level physics in this rare 8-bit build of the classic PC title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-the-europe', 'Game Gear', 'Lion King, The (Europe)', '1994', 'Platform', 'Virgin Interactive', '1', 'Movie', 'Side-scrolling platformer.', 'Grow from a cub to a king and defeat Scar.', 'A beautiful and difficult movie tie-in.', 'The Lion King (Europe) features incredible animation and catchy music. Navigate the Pride Lands and survive the stampede in this visually vibrant and high-quality 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lion-king-the-usa', 'Game Gear', 'Lion King, The (USA)', '1994', 'Platform', 'Virgin Interactive', '1', 'Movie', 'Side-scrolling platformer.', 'Grow from a cub to a king and defeat Scar.', 'North American release of the Disney masterpiece.', 'Experience Simba''s journey in the US version of The Lion King. With its challenging platforming and stunning 8-bit color, it stands as one of the best-looking games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-world-the---jurassic-park-usa', 'Game Gear', 'Lost World, The - Jurassic Park (USA)', '1994', 'Action', 'Ocean Software', '1', 'Movie', 'Side-scrolling action platformer.', 'Infiltrate the second island and survive the dinosaurs.', 'A late-release Jurassic sequel with refined gameplay.', 'The Lost World: Jurassic Park features intense shooting and exploration. Battle rogue hunters and dangerous predators in this atmospheric and high-quality dinosaur sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lucky-dime-caper-the-usa-europe', 'Game Gear', 'Lucky Dime Caper, The (USA, Europe)', '1991', 'Platform', 'Sega', '1', 'Platform', 'Side-scrolling platformer.', 'Recover Scrooge''s lucky dime from the evil witch.', 'A foundational and charming Donald Duck adventure.', 'The Lucky Dime Caper features excellent 8-bit graphics and tight controls. Travel the world and use your mallet or frisbee to defeat enemies in this Sega handheld classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lunar---sanposuru-gakuen-japan', 'Game Gear', 'Lunar - Sanposuru Gakuen (Japan)', '1995', 'Adventure', 'Game Arts', '1', 'RPG', 'Tactical strategy RPG.', 'Guide your students through a magical school adventure.', 'A deep RPG spin-off of the legendary Lunar series.', 'Lunar: Sanposuru Gakuen features beautiful turn-based combat and a rich story. Explore the floating island and master magical abilities in this high-quality Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-95-usa-europe', 'Game Gear', 'Madden NFL ''95 (USA, Europe)', '1994', 'Sports', 'Electronic Arts', '2', 'Football', 'Sports simulation (Football).', 'Win the Super Bowl with updated 1995 rosters.', 'A detailed and professional portable NFL sim.', 'Madden NFL ''95 brings the gridiron to your pocket. Featuring real players and team stats, it offers a deep and strategic take on American football for handheld gamers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-96-usa-europe', 'Game Gear', 'Madden NFL ''96 (USA, Europe)', '1995', 'Sports', 'Electronic Arts', '2', 'Football', 'Sports simulation (Football).', 'Lead your team to victory in the 1996 season.', 'The refined and final 8-bit Madden experience.', 'Madden NFL ''96 features updated plays and better AI. Master the play-calling and field action in this comprehensive and polished portable football simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari-a---doki-doki-vacation-english---translated', 'Game Gear', 'Madou Monogatari A - Doki-Doki Vacation (English - Translated)', '1994', 'RPG', 'Compile', '1', 'Dungeon Crawler', 'Turn-based dungeon crawler.', 'Help Arle pass her magical kindergarten exam.', 'Fan-translated version of the charming dungeon RPG.', 'Madou Monogatari A (English) lets Western players enjoy the prequel to Puyo Puyo. Navigate 3D dungeons and engage in cute yet challenging battles in this colorful translated quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari-a---dokidoki-vacation-japan', 'Game Gear', 'Madou Monogatari A - Dokidoki Vacation (Japan)', '1994', 'RPG', 'Compile', '1', 'Dungeon Crawler', 'Turn-based dungeon crawler.', 'Help Arle pass her magical kindergarten exam.', 'A Japanese exclusive RPG with a unique combat system.', 'Madou Monogatari A: Doki-Doki Vacation features beautiful 8-bit art and 3D navigation. Help the young mage Arle solve puzzles and defeat monsters in this heartwarming handheld RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari-i---3-tsu-no-madoukyuu-japan', 'Game Gear', 'Madou Monogatari I - 3-Tsu no Madoukyuu (Japan)', '1993', 'RPG', 'Compile', '1', 'Dungeon Crawler', 'Turn-based dungeon crawler.', 'Conquer the three magical towers to become a mage.', 'The origin story of the Puyo Puyo universe.', 'Madou Monogatari I is a classic first-person dungeon crawler. Featuring voice clips and expressive sprites, explore dangerous towers to earn your magic license in this technical 8-bit gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari-i---mitsu-no-madouryoku-english', 'Game Gear', 'Madou Monogatari I - Mitsu no Madouryoku (English)', '1994', 'RPG', 'Compile', '1', 'Dungeon Crawler', 'First-person dungeon crawler.', 'Conquer the towers and graduate from magic school.', 'English fan-translated version of the first Madou epic.', 'Madou Monogatari I (English) brings the origin of Arle Nadja to Western players. Navigate 3D labyrinths, battle quirky monsters, and experience the charming RPG roots of the Puyo Puyo universe in full English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari-ii---arle-16-sai-english-translated', 'Game Gear', 'Madou Monogatari II - Arle 16-Sai (English Translated)', '1994', 'RPG', 'Compile', '1', 'Dungeon Crawler', 'First-person dungeon crawler.', 'Escape the ancient ruins and defeat Schezo Wegey.', 'English fan-translated sequel starring 16-year-old Arle.', 'Madou Monogatari II (English) follows Arle as she is kidnapped by a dark wizard. Explore treacherous ruins and master elemental spells in this beautifully illustrated and story-rich 8-bit handheld RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari-ii---arle-16-sai-japan', 'Game Gear', 'Madou Monogatari II - Arle 16-Sai (Japan)', '1994', 'RPG', 'Compile', '1', 'Dungeon Crawler', 'First-person dungeon crawler.', 'Escape the ancient ruins and defeat Schezo Wegey.', 'The original Japanese version of Arle’s second quest.', 'Madou Monogatari II: Arle 16-Sai features impressive voice clips and expressive character portraits. It’s a technical showcase for the Game Gear, blending traditional dungeon crawling with a heartwarming narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari-iii---kyuukyoku-joou-sama-english-translated', 'Game Gear', 'Madou Monogatari III - Kyuukyoku Joou-sama (English Translated)', '1995', 'RPG', 'Compile', '1', 'Dungeon Crawler', 'First-person dungeon crawler.', 'Defeat the Queen and finish your magical journey.', 'English fan-translated finale of the Game Gear trilogy.', 'Madou Monogatari III (English) sees Arle facing her toughest challenges yet. Use strategy and magic to navigate complex 3D dungeons in this polished and humorous 8-bit RPG, now fully accessible to English speakers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari-iii---kyuukyoku-joou-sama-japan', 'Game Gear', 'Madou Monogatari III - Kyuukyoku Joou-sama (Japan)', '1995', 'RPG', 'Compile', '1', 'Dungeon Crawler', 'First-person dungeon crawler.', 'Defeat the Queen and finish your magical journey.', 'The original Japanese version of the trilogy’s conclusion.', 'Experience the final chapter of the Madou series on Game Gear. Madou Monogatari III features refined combat mechanics and stunning 8-bit art, solidifying its place as one of the system’s best RPG experiences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madou-monogatari-iii---kyuukyoku-joou-sama-japan-v11', 'Game Gear', 'Madou Monogatari III - Kyuukyoku Joou-sama (Japan) (v1.1)', '1995', 'RPG', 'Compile', '1', 'Dungeon Crawler', 'First-person dungeon crawler.', 'Defeat the Queen and finish your magical journey.', 'Updated Japanese version of the third Madou quest.', 'This v1.1 of Madou Monogatari III features minor bug fixes and balance tweaks. Explore the depths of the 3D dungeons and master Arle''s magic in the most polished version of this handheld classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-knight-rayearth-japan', 'Game Gear', 'Magic Knight Rayearth (Japan)', '1994', 'RPG', 'Bandai', '1', 'Anime', 'Strategy RPG.', 'Lead the Magic Knights to save the world of Cephiro.', 'A Japanese exclusive based on the hit CLAMP anime.', 'Magic Knight Rayearth features beautiful cutscenes and tactical turn-based combat. Control Hikaru, Umi, and Fuu as they pilot their Rune Gods to defeat Zagato in this vibrant and story-driven 8-bit RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magic-knight-rayearth-2---making-of-magic-knight-japan', 'Game Gear', 'Magic Knight Rayearth 2 - Making of Magic Knight (Japan)', '1995', 'Adventure', 'Bandai', '1', 'Anime', 'Digital Artbook / Fan Disc.', 'Explore the world and development of Rayearth.', 'A unique Japanese exclusive "making-of" title.', 'Magic Knight Rayearth 2: Making of Magic Knight is a fan-service treasure. It features character bios, art galleries, and mini-games that expand on the lore of the anime and the first Game Gear game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-puzzle-popils-world-enja', 'Game Gear', 'Magical Puzzle Popils (World) (En,Ja)', '1995', 'Puzzle', 'Hudson Soft', '1', 'Puzzle', 'Puzzle-platformer.', 'Rescue the princess by manipulating the environment.', 'A creative and charming logic-based puzzle quest.', 'Magical Puzzle Popils (known as Popils) is an addictive gem. Break blocks and time your movements to reunite a boy and a princess across dozens of increasingly difficult 8-bit puzzle stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-taruruuto-kun-japan', 'Game Gear', 'Magical Taruruuto-kun (Japan)', '1992', 'Action', 'Bandai', '1', 'Anime', 'Side-scrolling platformer.', 'Use your magical powers to clear each level.', 'A Japanese exclusive based on the wacky anime.', 'Magical Taruruuto-kun features bright, colorful graphics and creative mechanics. Use Taruruuto''s magic to fly and manipulate items in this charming and polished 8-bit handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majors-pro-baseball-the-usa-europe', 'Game Gear', 'Majors Pro Baseball, The (USA, Europe)', '1994', 'Sports', 'Iguana Entertainment', '2', 'Baseball', 'Sports simulation (Baseball).', 'Lead your pro team to the championship.', 'A fast and accessible portable baseball simulation.', 'The Majors Pro Baseball brings the diamond to your pocket. Featuring a full roster of teams and smooth batting/pitching gameplay, it’s a solid and competitive sports title for Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mappy-japan', 'Game Gear', 'Mappy (Japan)', '1990', 'Arcade', 'Namco', '1', 'Classic', 'Arcade action.', 'Recover all stolen items while avoiding the cats.', 'A vibrant portable port of the Namco arcade classic.', 'Mappy (Japan) features the iconic police mouse in a high-stakes game of cat and mouse. Bounce on trampolines and use doors to outsmart the Mewkies in this colorful and faithful 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marble-madness-usa-europe', 'Game Gear', 'Marble Madness (USA, Europe)', '1991', 'Action', 'Atari Games', '1', 'Arcade', 'Isometric ball-rolling.', 'Guide the marble to the goal before time runs out.', 'A technical and challenging port of the arcade hit.', 'Marble Madness features impressive 8-bit physics and pseudo-3D environments. Navigate through hazard-filled courses in a test of precision and speed that shines on the handheld''s color screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('markos-magic-football-usa-europe-enfrdees', 'Game Gear', 'Marko''s Magic Football (USA, Europe) (En,Fr,De,Es)', '1994', 'Sports', 'Domark', '2', 'Soccer', 'Side-scrolling platformer.', 'Use your soccer ball to defeat the polluters.', 'A unique sports-themed action platformer.', 'Marko''s Magic Football features incredibly smooth animation and creative gameplay. Use your ball as a weapon and a tool to solve puzzles in this polished and vibrant European-exclusive quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-usa-europe', 'Game Gear', 'Mega Man (USA, Europe)', '1994', 'Action', 'Capcom', '1', 'Action', 'Side-scrolling action platformer.', 'Defeat the Robot Masters and stop Dr. Wily.', 'A rare and high-octane 8-bit Mega Man exclusive.', 'Mega Man on Game Gear is a legendary collectible. Combining levels from the NES classics, it features fast-paced shooting, iconic boss battles, and vibrant colors in one of the system''s most intense action games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megami-tensei-gaiden---last-bible-english', 'Game Gear', 'Megami Tensei Gaiden - Last Bible (English)', '1993', 'RPG', 'Multimedia Intelligence Transfer', '1', 'JRPG', 'Turn-based RPG.', 'Capture and fuse monsters to save the world.', 'English fan-translated version of the iconic spin-off.', 'Megami Tensei Gaiden: Last Bible (English) brings the legendary monster-collecting series to Western fans. Recruit demons and explore a vast fantasy world in this deep and addictive handheld RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megami-tensei-gaiden---last-bible-japan', 'Game Gear', 'Megami Tensei Gaiden - Last Bible (Japan)', '1993', 'RPG', 'Multimedia Intelligence Transfer', '1', 'JRPG', 'Turn-based RPG.', 'Capture and fuse monsters to save the world.', 'The original Japanese monster-collecting adventure.', 'Last Bible (Japan) is a foundational entry in the Megaten franchise. Featuring a complex demon-fusion system and tactical turn-based battles, it offers hundreds of hours of 8-bit portable RPG depth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megami-tensei-gaiden---last-bible-s-english', 'Game Gear', 'Megami Tensei Gaiden - Last Bible S (English)', '1995', 'RPG', 'Multimedia Intelligence Transfer', '1', 'JRPG', 'Turn-based RPG.', 'Stop the apocalypse in a world of demons and humans.', 'English fan-translated version of the expanded sequel.', 'Last Bible S (English) lets players experience the enhanced "Special" version of the game. Featuring improved graphics and more monsters to recruit, it’s a definitive handheld RPG experience in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megami-tensei-gaiden---last-bible-s-japan', 'Game Gear', 'Megami Tensei Gaiden - Last Bible S (Japan)', '1995', 'RPG', 'Multimedia Intelligence Transfer', '1', 'JRPG', 'Turn-based RPG.', 'Stop the apocalypse in a world of demons and humans.', 'The enhanced Japanese "Special" monster-collecting RPG.', 'Last Bible S is an upgraded version featuring more detailed sprites and expanded story elements. Dive into the world of demon summoning and fusion in this high-quality 8-bit portable classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mick-&-mack-as-the-global-gladiators-usa-europe', 'Game Gear', 'Mick & Mack as the Global Gladiators (USA, Europe)', '1993', 'Platform', 'Virgin Interactive', '1', 'Platform', 'Side-scrolling platformer.', 'Clean up the environment and defeat the polluters.', 'A fast-paced and visually busy action platformer.', 'Global Gladiators features Mick and Mack in a quest to save the Earth. Blast through vibrant, slime-filled levels with a goo-gun in this technically impressive and high-energy 8-bit handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mouse-densetsu-no-oukoku---legend-of-illusion-japan', 'Game Gear', 'Mickey Mouse Densetsu no Oukoku - Legend of Illusion (Japan)', '1994', 'Platform', 'Sega', '1', 'Platform', 'Side-scrolling platformer.', 'Find the lost book and stop the evil queen.', 'The Japanese version of Legend of Illusion.', 'Mickey Mouse Densetsu no Oukoku is a masterpiece of handheld animation. Guide Mickey through a fairytale world in this visually stunning finale to the 8-bit Illusion trilogy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mouse-no-castle-illusion-japan', 'Game Gear', 'Mickey Mouse no Castle Illusion (Japan)', '1990', 'Platform', 'Sega', '1', 'Platform', 'Side-scrolling platformer.', 'Rescue Minnie Mouse from the witch Mizrabel.', 'The Japanese version of Castle of Illusion.', 'Mickey Mouse no Castle Illusion is one of the most beloved games on the system. Featuring creative levels and perfect controls, it is the gold standard for 8-bit Disney platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mouse-no-mahou-no-crystal-japan', 'Game Gear', 'Mickey Mouse no Mahou no Crystal (Japan)', '1991', 'Action', 'Sega', '1', 'Platform', 'Side-scrolling platformer.', 'Reclaim the "Good Magic" from the Phantom Castle.', 'The Japanese version of Land of Illusion.', 'Mickey Mouse no Mahou no Crystal features deep level design and unique power-ups. Explore a massive fantasy kingdom and help Mickey restore peace in this technical handheld marvel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickeys-ultimate-challenge-usa-europe', 'Game Gear', 'Mickey''s Ultimate Challenge (USA, Europe)', '1994', 'Puzzle', 'Davidson & Associates', '1', 'Educational', 'Puzzle-adventure.', 'Solve puzzles to win a chance to enter the castle.', 'A brain-teasing Disney quest for younger players.', 'Mickey''s Ultimate Challenge features a variety of logic puzzles and mini-games. It’s a charming and accessible title that focuses on thinking and observation rather than high-speed action.');